(316753,35195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона співає вдома, але вчора ... в студії.'::text,'співала'::text,'співає'::text,NULL::text,'Зазвичай вона співає вдома, але вчора співала в студії.'::text),
(316752,35195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente canta en casa, pero ayer ... en un estudio.'::text,'cantó'::text,'canta'::text,NULL::text,'Normalmente canta en casa, pero ayer cantó en un estudio.'::text),
(316751,35195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle chante à la maison, mais hier elle ... dans un studio.'::text,'a chanté'::text,'chante'::text,NULL::text,'D''habitude elle chante à la maison, mais hier elle a chanté dans un studio.'::text),
(316754,35195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde evde şarkı söyler ama dün bir stüdyoda ...'::text,'şarkı söyledi'::text,'şarkı söyler'::text,NULL::text,'Genelde evde şarkı söyler ama dün bir stüdyoda şarkı söyledi.'::text),
(316755,35195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában otthon énekel, de tegnap egy stúdióban ...'::text,'énekelt'::text,'énekel'::text,NULL::text,'Általában otthon énekel, de tegnap egy stúdióban énekelt.'::text),
(316758,35196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, anscheinend ... sie gerade in ein riesiges Mikro.'::text,'singt'::text,'singt'::text,'singt'::text,'Also, anscheinend singt sie gerade in ein riesiges Mikro.'::text),
(316762,35196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, вона саме зараз ... в гігантський мікрофон.'::text,'співає'::text,'співає'::text,'співає'::text,'Короче, кажуть, вона саме зараз співає в гігантський мікрофон.'::text),
(316761,35196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ahora mismo ... en un micrófono enorme.'::text,'está cantando'::text,'canta'::text,'está cantando'::text,'Vale, pues al parecer ahora mismo está cantando en un micrófono enorme.'::text),
(316760,35196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle ... dans un micro énorme en ce moment.'::text,'est en train de chanter'::text,'chante'::text,'est en train de chanter'::text,'Bon, apparemment elle est en train de chanter dans un micro énorme en ce moment.'::text),
(316763,35196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan şu an kocaman bir mikrofona ...'::text,'şarkı söylüyor'::text,'şarkı söyler'::text,'şarkı söylüyor'::text,'Tamam, anlaşılan şu an kocaman bir mikrofona şarkı söylüyor.'::text),
(316764,35196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag most épp egy óriási mikrofonba ...'::text,'énekel'::text,'énekel'::text,'énekel'::text,'Szóval, állítólag most épp egy óriási mikrofonba énekel.'::text),
(316767,35197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er meinte, sie singt leise, aber heute ... sie richtig laut.'::text,'singt'::text,'singt'::text,NULL::text,'Mädel, er meinte, sie singt leise, aber heute singt sie richtig laut.'::text),
(316771,35197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він казав, що вона співає тихо, але сьогодні ... дуже голосно.'::text,'співає'::text,'співає'::text,NULL::text,'Подруго, він казав, що вона співає тихо, але сьогодні співає дуже голосно.'::text),
(316770,35197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él dijo que canta bajito, pero hoy ... superfuerte.'::text,'está cantando'::text,'canta'::text,NULL::text,'Tía, él dijo que canta bajito, pero hoy está cantando superfuerte.'::text),
(316769,35197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il a dit qu''elle chante doucement, mais aujourd''hui elle ... super fort.'::text,'est en train de chanter'::text,'chante'::text,NULL::text,'Ma belle, il a dit qu''elle chante doucement, mais aujourd''hui elle est en train de chanter super fort.'::text),
(316772,35197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, onun yumuşak sesle şarkı söylediğini söyledi ama bugün çok yüksek sesle ...'::text,'şarkı söylüyor'::text,'şarkı söyler'::text,NULL::text,'Kızım, onun yumuşak sesle şarkı söylediğini söyledi ama bugün çok yüksek sesle şarkı söylüyor.'::text),
(316773,35197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy halkan énekel, de ma nagyon hangosan ...'::text,'énekel'::text,'énekel'::text,NULL::text,'Csajszi, azt mondta, hogy halkan énekel, de ma nagyon hangosan énekel.'::text),
(316776,35198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, der Tontechniker hat mir erzählt, dass sie auf einem großen Konzert ...'::text,'singen wird'::text,'singt'::text,'sang'::text,'Hör zu, der Tontechniker hat mir erzählt, dass sie auf einem großen Konzert singen wird.'::text),
(316780,35198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, звукорежисер сказав мені, що вона ... на великому концерті.'::text,'співатиме'::text,'співає'::text,'співала'::text,'Слухай, звукорежисер сказав мені, що вона співатиме на великому концерті.'::text),
(316779,35198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, el técnico de sonido me dijo que ... en un gran concierto.'::text,'cantará'::text,'canta'::text,'cantó'::text,'Escucha, el técnico de sonido me dijo que cantará en un gran concierto.'::text),
(316778,35198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, l''ingénieur du son m''a dit qu''elle ... à un grand concert.'::text,'chantera'::text,'chante'::text,'a chanté'::text,'Écoute, l''ingénieur du son m''a dit qu''elle chantera à un grand concert.'::text),
(316781,35198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ses mühendisi bana dedi ki büyük bir konserde ...'::text,'şarkı söyleyecek'::text,'şarkı söyler'::text,'şarkı söyledi'::text,'Dinle, ses mühendisi bana dedi ki büyük bir konserde şarkı söyleyecek.'::text),
(316782,35198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a hangmérnök azt mondta, hogy egy nagy koncerten ...'::text,'fog énekelni'::text,'énekel'::text,'énekelt'::text,'Figyelj, a hangmérnök azt mondta, hogy egy nagy koncerten fog énekelni.'::text),
(316785,35199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast die Kopfhörer auf: Du ... diesen Song wieder singen. Ikonisch.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Du hast die Kopfhörer auf: Du wirst diesen Song wieder singen. Ikonisch.'::text),
(316789,35199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У тебе вже навушники: ти ... цю пісню знову. Іконічно.'::text,'збираєшся заспівати'::text,'заспіваєш'::text,'збираєшся заспівати'::text,'У тебе вже навушники: ти збираєшся заспівати цю пісню знову. Іконічно.'::text),
(316788,35199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llevas los cascos puestos: ... esa canción otra vez. Icónico.'::text,'vas a cantar'::text,'cantarás'::text,'vas a cantar'::text,'Llevas los cascos puestos: vas a cantar esa canción otra vez. Icónico.'::text),
(316787,35199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as le casque sur les oreilles : tu ... cette chanson encore une fois. Iconique.'::text,'vas chanter'::text,'chanteras'::text,'vas chanter'::text,'Tu as le casque sur les oreilles : tu vas chanter cette chanson encore une fois. Iconique.'::text),
(316790,35199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kulaklıklar takılı: yine o şarkıyı ..., resmen ikonik.'::text,'söyleyeceksin'::text,'söyleyeceksin'::text,'söyleyeceksin'::text,'Kulaklıklar takılı: yine o şarkıyı söyleyeceksin, resmen ikonik.'::text),
(316791,35199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rajtad a fejhallgató: újra ... azt a dalt. Ikonikus.'::text,'el fogod énekelni'::text,'el fogod énekelni'::text,'el fogod énekelni'::text,'Rajtad a fejhallgató: újra el fogod énekelni azt a dalt. Ikonikus.'::text),
(316794,35200,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du lachst und sagst: „Okay, ich ... es noch mal singen!“ Ikonisch.'::text,'werde'::text,'werde'::text,NULL::text,'Du lachst und sagst: „Okay, ich werde es noch mal singen!“ Ikonisch.'::text),
(316798,35200,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти смієшся і кажеш: «Окей, я ... співати її знову!» Іконічно.'::text,'буду'::text,'збираюся'::text,NULL::text,'Ти смієшся і кажеш: «Окей, я буду співати її знову!» Іконічно.'::text),
(316797,35200,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ríes y dices: «¡Vale, ... otra vez!». Icónico.'::text,'la cantaré'::text,'voy a cantarla'::text,NULL::text,'Te ríes y dices: «¡Vale, la cantaré otra vez!». Icónico.'::text),
(316796,35200,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ris et tu dis : « OK, je ... encore ! » Iconique.'::text,'la chanterai'::text,'vais la chanter'::text,NULL::text,'Tu ris et tu dis : « OK, je la chanterai encore ! » Iconique.'::text),
(316799,35200,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gülüp “Tamam, onu yine ...!” diyorsun. İkonik.'::text,'söyleyeceğim'::text,'söyleyeceğim'::text,NULL::text,'Gülüp “Tamam, onu yine söyleyeceğim!” diyorsun. İkonik.'::text),
(316800,35200,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nevetsz, és azt mondod: „Oké, újra el ... énekelni!” Ikonikus.'::text,'fogom'::text,'fogom'::text,NULL::text,'Nevetsz, és azt mondod: „Oké, újra el fogom énekelni!” Ikonikus.'::text),
(316812,35202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie singt sehr laut, also ... sie vom Mikro zurücktreten.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Sie singt sehr laut, also sollte sie vom Mikro zurücktreten.'::text),
(316816,35202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона співає дуже голосно, тож вона ... відступити від мікрофона.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Вона співає дуже голосно, тож вона мала б відступити від мікрофона.'::text),
(316815,35202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Canta muy fuerte, así que ... apartarse del micrófono.'::text,'debería'::text,'debería'::text,'debería'::text,'Canta muy fuerte, así que debería apartarse del micrófono.'::text),
(316814,35202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle chante très fort, alors elle ... s''éloigner du micro.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Elle chante très fort, alors elle devrait s''éloigner du micro.'::text),
(316817,35202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok yüksek sesle şarkı söylüyor, bu yüzden mikrofondan geri ...'::text,'çekilmeli'::text,'çekilmeli'::text,'çekilmeli'::text,'Çok yüksek sesle şarkı söylüyor, bu yüzden mikrofondan geri çekilmeli.'::text),
(316818,35202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon hangosan énekel, ezért ... hátrébb lépnie a mikrofontól.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Nagyon hangosan énekel, ezért kellene hátrébb lépnie a mikrofontól.'::text),
(325803,36201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: ... Besuch dauert heute 30 Minuten.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Bericht: Dieser Besuch dauert heute 30 Minuten.'::text),
(325807,36201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: ... візит сьогодні триває 30 хвилин.'::text,'цей'::text,'ці'::text,'ті'::text,'Звіт: цей візит сьогодні триває 30 хвилин.'::text),
(325806,36201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: ... visita de hoy dura 30 minutos.'::text,'esta'::text,'estas'::text,'esas'::text,'Informe: esta visita de hoy dura 30 minutos.'::text),
(325805,36201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : ... visite d''aujourd''hui dure 30 minutes.'::text,'cette'::text,'ces'::text,'ces'::text,'Rapport : cette visite d''aujourd''hui dure 30 minutes.'::text),
(325808,36201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: bugünkü ... ziyaret 30 dakika sürüyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Rapor: bugünkü bu ziyaret 30 dakika sürüyor.'::text),
(325809,36201,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: ... a látogatás ma 30 percig tart.'::text,'ez'::text,'ezek'::text,'azok'::text,'Jelentés: ez a látogatás ma 30 percig tart.'::text),
(325812,36202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Patientin liebt den Besuch ... Freundin, weil es ein Besuch ist.'::text,'ihrer'::text,'seiner'::text,'seiner'::text,'Die Patientin liebt den Besuch ihrer Freundin, weil es ein Besuch ist.'::text),
(325816,36202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пацієнтка обожнює візит ... подруги, бо це візит.'::text,'своєї'::text,'своєї'::text,'своєї'::text,'Пацієнтка обожнює візит своєї подруги, бо це візит.'::text),
(325815,36202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A la paciente le encanta la visita de ... amiga porque es una visita.'::text,'su'::text,'su'::text,'su'::text,'A la paciente le encanta la visita de su amiga porque es una visita.'::text),
(325814,36202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La patiente adore la visite de ... amie parce que c''est une visite.'::text,'son'::text,'son'::text,'son'::text,'La patiente adore la visite de son amie parce que c''est une visite.'::text),
(325817,36202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ... arkadaşının ziyaretine bayılıyor çünkü bu bir ziyaret.'::text,'onun'::text,'onun'::text,'onun'::text,'Hasta onun arkadaşının ziyaretine bayılıyor çünkü bu bir ziyaret.'::text),
(325818,36202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A betegnő imádja a ... látogatását, mert ez egy látogatás.'::text,'barátnője'::text,'barátnője'::text,'barátnője'::text,'A betegnő imádja a barátnője látogatását, mert ez egy látogatás.'::text),
(325830,36204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Besuche in einer Woche! Sie ist total besessen!'::text,'Drei'::text,'Dritte'::text,'Dreien'::text,'Drei Besuche in einer Woche! Sie ist total besessen!'::text),
(325834,36204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... візити за один тиждень! Вона просто одержима!'::text,'Три'::text,'Третій'::text,'Трійки'::text,'Три візити за один тиждень! Вона просто одержима!'::text),
(325833,36204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... visitas en una semana! ¡Está totalmente obsesionada!'::text,'Tres'::text,'Tercera'::text,'Tres'::text,'¡Tres visitas en una semana! ¡Está totalmente obsesionada!'::text),
(325832,36204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... visites en une semaine ! Elle est complètement obsédée !'::text,'Trois'::text,'Troisième'::text,'Trois'::text,'Trois visites en une semaine ! Elle est complètement obsédée !'::text),
(325835,36204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir haftada ... ziyaret! Resmen takıntılı!'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Bir haftada üç ziyaret! Resmen takıntılı!'::text),
(325836,36204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... látogatás egy hét alatt! Teljesen megszállott!'::text,'Három'::text,'Harmadik'::text,'Hármasok'::text,'Három látogatás egy hét alatt! Teljesen megszállott!'::text),
(325848,36206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend hat ihre Freundin beim Besuch ... Blumen bekommen.'::text,'einige'::text,'viel'::text,'irgendwelche'::text,'Bestie, anscheinend hat ihre Freundin beim Besuch einige Blumen bekommen.'::text),
(325852,36206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, її подруга отримала під час візиту ... квіти.'::text,'якісь'::text,'багато'::text,'будь-які'::text,'Подруго, кажуть, її подруга отримала під час візиту якісь квіти.'::text),
(325851,36206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer su amiga recibió ... flores durante la visita.'::text,'algunas'::text,'mucha'::text,'cualquier'::text,'Tía, al parecer su amiga recibió algunas flores durante la visita.'::text),
(325850,36206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma meilleure amie, apparemment sa copine a reçu ... fleurs pendant la visite.'::text,'des'::text,'beaucoup de'::text,'n''importe quelles'::text,'Ma meilleure amie, apparemment sa copine a reçu des fleurs pendant la visite.'::text),
(325853,36206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan arkadaşı ziyarette ... çiçek almış.'::text,'birkaç'::text,'çok'::text,'herhangi bir'::text,'Kanka, anlaşılan arkadaşı ziyarette birkaç çiçek almış.'::text),
(325854,36206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a barátnője kapott ... virágot a látogatáskor.'::text,'néhány'::text,'sok'::text,'bármilyen'::text,'Csajszi, állítólag a barátnője kapott néhány virágot a látogatáskor.'::text),
(325857,36207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Für den Besuch ... Tulpen und ein Ballon da.'::text,'sind'::text,'ist'::text,'sein'::text,'Für den Besuch sind Tulpen und ein Ballon da.'::text),
(325861,36207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Для візиту ... тюльпани й повітряна кулька.'::text,'є'::text,'є'::text,'бути'::text,'Для візиту є тюльпани й повітряна кулька.'::text),
(325860,36207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tulipanes y un globo para la visita.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay tulipanes y un globo para la visita.'::text),
(325859,36207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des tulipes et un ballon pour la visite.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des tulipes et un ballon pour la visite.'::text),
(325862,36207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaret için laleler ve bir balon ...'::text,'var'::text,'var'::text,'olmak'::text,'Ziyaret için laleler ve bir balon var.'::text),
(325863,36207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogatáshoz tulipánok és egy lufi ...'::text,'vannak'::text,'van'::text,'lenni'::text,'A látogatáshoz tulipánok és egy lufi vannak.'::text),
(325866,36208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besuch ist kurz, ... die Patientin ist sehr glücklich.'::text,'aber'::text,'weil'::text,'also'::text,'Der Besuch ist kurz, aber die Patientin ist sehr glücklich.'::text),
(325870,36208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візит короткий, ... пацієнтка дуже щаслива.'::text,'але'::text,'бо'::text,'тому'::text,'Візит короткий, але пацієнтка дуже щаслива.'::text),
(325869,36208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visita es corta, ... la paciente está muy contenta.'::text,'pero'::text,'porque'::text,'así que'::text,'La visita es corta, pero la paciente está muy contenta.'::text),
(325868,36208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visite est courte, ... la patiente est très heureuse.'::text,'mais'::text,'parce que'::text,'donc'::text,'La visite est courte, mais la patiente est très heureuse.'::text),
(325871,36208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaret kısa ... hasta çok mutlu.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Ziyaret kısa ama hasta çok mutlu.'::text),
