(308928,34326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hauskatze kreuzt ihre beiden vorderen ...'::text,'Pfoten.'::text,'Pfote.'::text,'Pfoten.'::text,'Die Hauskatze kreuzt ihre beiden vorderen Pfoten.'::text),
(308932,34326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Домашня кішка схрещує дві передні ...'::text,'лапи.'::text,'лапа.'::text,'лапи.'::text,'Домашня кішка схрещує дві передні лапи.'::text),
(308931,34326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gata doméstica cruza sus dos ... delanteras.'::text,'patas'::text,'pata'::text,'patas'::text,'La gata doméstica cruza sus dos patas delanteras.'::text),
(308930,34326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat de compagnie croise ses deux ... avant.'::text,'pattes'::text,'patte'::text,'pattes'::text,'Le chat de compagnie croise ses deux pattes avant.'::text),
(308933,34326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evcil kedi iki ön ... çaprazlıyor.'::text,'patisini'::text,'patisini'::text,'patisini'::text,'Evcil kedi iki ön patisini çaprazlıyor.'::text),
(308934,34326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házimacska keresztbe teszi a két mellső ...'::text,'mancsát.'::text,'mancsát.'::text,'mancsát.'::text,'A házimacska keresztbe teszi a két mellső mancsát.'::text),
(308937,34327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Mein Haustier hält sich für ... Tiger!'::text,'einen'::text,'einen'::text,'den'::text,'Katastrophe! Mein Haustier hält sich für einen Tiger!'::text),
(308941,34327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Мій улюбленець думає, що він ... тигр!'::text,''::text,NULL::text,NULL::text,'Катастрофа! Мій улюбленець думає, що він тигр!'::text),
(308940,34327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Catástrofe! ¡Mi mascota cree que es ... tigre!'::text,'un'::text,'un'::text,'el'::text,'¡Catástrofe! ¡Mi mascota cree que es un tigre!'::text),
(308939,34327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Mon animal croit qu''il est ... tigre !'::text,'un'::text,'un'::text,'le'::text,'Catastrophe ! Mon animal croit qu''il est un tigre !'::text),
(308942,34327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Evcil hayvanım kendini ... kaplan sanıyor!'::text,'bir'::text,'bir'::text,NULL::text,'Felaket! Evcil hayvanım kendini bir kaplan sanıyor!'::text),
(308943,34327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A kedvencem azt hiszi, hogy ő ... tigris!'::text,'egy'::text,'egy'::text,'a'::text,'Katasztrófa! A kedvencem azt hiszi, hogy ő egy tigris!'::text),
(308946,34328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Spielzeugmaus ist der schlimmste Feind meines Haustiers!'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Spielzeugmaus ist der schlimmste Feind meines Haustiers!'::text),
(308950,34328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... іграшкова мишка — найгірший ворог мого улюбленця!'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця іграшкова мишка — найгірший ворог мого улюбленця!'::text),
(308949,34328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... ratón de juguete es el peor enemigo de mi mascota!'::text,'Este'::text,'Estos'::text,'Esos'::text,'¡Este ratón de juguete es el peor enemigo de mi mascota!'::text),
(308948,34328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... souris en jouet est la pire ennemie de mon animal !'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette souris en jouet est la pire ennemie de mon animal !'::text),
(308951,34328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... oyuncak fare evcil hayvanımın en büyük düşmanı!'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu oyuncak fare evcil hayvanımın en büyük düşmanı!'::text),
(308952,34328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a játékegér a kedvencem legnagyobb ellensége!'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a játékegér a kedvencem legnagyobb ellensége!'::text),
(308955,34329,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann beobachtet ... Hauskatze auf dem Teppich.'::text,'seine'::text,'ihre'::text,'seine'::text,'Der Mann beobachtet seine Hauskatze auf dem Teppich.'::text),
(308959,34329,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік спостерігає за ... кішкою на килимі.'::text,'своєю'::text,'своєю'::text,'своєю'::text,'Чоловік спостерігає за своєю кішкою на килимі.'::text),
(308958,34329,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre observa a ... gata en la alfombra.'::text,'su'::text,'su'::text,'su'::text,'El hombre observa a su gata en la alfombra.'::text),
(308957,34329,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme regarde ... chat sur le tapis.'::text,'son'::text,'son'::text,'son'::text,'L''homme regarde son chat sur le tapis.'::text),
(308960,34329,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam halının üstündeki ... kedisini izliyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam halının üstündeki onun kedisini izliyor.'::text),
(308961,34329,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi figyeli a ... a szőnyegen.'::text,'macskáját'::text,'macskáját'::text,'macskáját'::text,'A férfi figyeli a macskáját a szőnyegen.'::text),
(308964,34330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... schaut die Hauskatze an? Die Spielzeugmaus.'::text,'Was'::text,'Wen'::text,'Wo'::text,'Was schaut die Hauskatze an? Die Spielzeugmaus.'::text),
(308968,34330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... дивиться домашня кішка? На іграшкову мишку.'::text,'На що'::text,'На кого'::text,'Куди'::text,'На що дивиться домашня кішка? На іграшкову мишку.'::text),
(308967,34330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... mira la gata? El ratón de juguete.'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué mira la gata? El ratón de juguete.'::text),
(308966,34330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... regarde le chat ? La souris en jouet.'::text,'Que'::text,'Qui'::text,'Où'::text,'Que regarde le chat ? La souris en jouet.'::text),
(308969,34330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evcil kedi ... bakıyor? Oyuncak fareye.'::text,'neye'::text,'kime'::text,'nereye'::text,'Evcil kedi neye bakıyor? Oyuncak fareye.'::text),
(308970,34330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... néz a macska? A játékegérre.'::text,'Mire'::text,'Kire'::text,'Hová'::text,'Mire néz a macska? A játékegérre.'::text),
(308973,34331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, das Haustier wird den ganzen Tag ... dem Teppich liegen.'::text,'auf'::text,'in'::text,'unter'::text,'Ey, das Haustier wird den ganzen Tag auf dem Teppich liegen.'::text),
(308977,34331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, улюбленець цілий день лежатиме ... килимі.'::text,'на'::text,'в'::text,'під'::text,'Йо, улюбленець цілий день лежатиме на килимі.'::text),
(308976,34331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la mascota va a estar tumbada todo el día ... la alfombra.'::text,'en'::text,'en'::text,'debajo de'::text,'Tío, la mascota va a estar tumbada todo el día en la alfombra.'::text),
(308975,34331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, l''animal va rester allongé ... le tapis toute la journée.'::text,'sur'::text,'dans'::text,'sous'::text,'Wesh, l''animal va rester allongé sur le tapis toute la journée.'::text),
(308978,34331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu evcil hayvan bütün gün halının ... yatacak.'::text,'üstünde'::text,'içinde'::text,'altında'::text,'Kanka, bu evcil hayvan bütün gün halının üstünde yatacak.'::text),
(308979,34331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a kis kedvenc egész nap a ... fog feküdni.'::text,'szőnyegen'::text,'szőnyegben'::text,'szőnyeg alatt'::text,'Figyu, a kis kedvenc egész nap a szőnyegen fog feküdni.'::text),
(308982,34332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hauskatze hat ... Beine.'::text,'vier'::text,'vierte'::text,'Vieren'::text,'Die Hauskatze hat vier Beine.'::text),
(308986,34332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У домашньої кішки ... лапи.'::text,'чотири'::text,'четверті'::text,'четвірки'::text,'У домашньої кішки чотири лапи.'::text),
(308985,34332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gata doméstica tiene ... patas.'::text,'cuatro'::text,'cuartas'::text,'cuatro'::text,'La gata doméstica tiene cuatro patas.'::text),
(308984,34332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chat de compagnie a ... pattes.'::text,'quatre'::text,'quatrièmes'::text,'quatre'::text,'Le chat de compagnie a quatre pattes.'::text),
(308987,34332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evcil kedinin ... bacağı var.'::text,'dört'::text,'dördüncü'::text,'dörtler'::text,'Evcil kedinin dört bacağı var.'::text),
(308988,34332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házimacskának ... lába van.'::text,'négy'::text,'negyedik'::text,'négyesek'::text,'A házimacskának négy lába van.'::text),
(298632,33182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... mich seine Hand an den Reisterrassen entlang.'::text,'zog'::text,'zieht'::text,'ziehen'::text,'Gestern zog mich seine Hand an den Reisterrassen entlang.'::text),
(298636,33182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора його рука ... мене вздовж рисових терас.'::text,'тягнула'::text,'тягне'::text,'тягнути'::text,'Учора його рука тягнула мене вздовж рисових терас.'::text),
(298635,33182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer su mano ... de mí por las terrazas de arroz.'::text,'tiró'::text,'tira'::text,'tirar'::text,'Ayer su mano tiró de mí por las terrazas de arroz.'::text),
(298634,33182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, sa main ... le long des rizières en terrasses.'::text,'m''a tiré'::text,'me tire'::text,'me tirer'::text,'Hier, sa main m''a tiré le long des rizières en terrasses.'::text),
(298637,33182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün eli beni pirinç terasları boyunca ...'::text,'çekti'::text,'çeker'::text,'çekmek'::text,'Dün eli beni pirinç terasları boyunca çekti.'::text),
(298638,33182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a keze ... engem a rizsteraszok mentén.'::text,'húzott'::text,'húz'::text,'húzni'::text,'Tegnap a keze húzott engem a rizsteraszok mentén.'::text),
(298641,33183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Hand zeigt normalerweise den Weg, aber gestern ... du auf der Schaukel. Respekt.'::text,'schaukeltest'::text,'schaukelst'::text,NULL::text,'Deine Hand zeigt normalerweise den Weg, aber gestern schaukeltest du auf der Schaukel. Respekt.'::text),
(298645,33183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай твоя рука показує дорогу, але вчора ти ... на гойдалці. Респект.'::text,'катався'::text,'катаєшся'::text,NULL::text,'Зазвичай твоя рука показує дорогу, але вчора ти катався на гойдалці. Респект.'::text),
(298644,33183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente tu mano señala el camino, pero ayer ... en el columpio. Mis respetos.'::text,'te columpiaste'::text,'te columpias'::text,NULL::text,'Normalmente tu mano señala el camino, pero ayer te columpiaste en el columpio. Mis respetos.'::text),
(298643,33183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude ta main montre le chemin, mais hier tu ... sur la balançoire. Respect.'::text,'t''es balancé'::text,'te balances'::text,NULL::text,'D''habitude ta main montre le chemin, mais hier tu t''es balancé sur la balançoire. Respect.'::text),
(298646,33183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elin genelde yolu gösterir ama dün salıncakta ... Helal olsun.'::text,'sallandın'::text,'sallanırsın'::text,NULL::text,'Elin genelde yolu gösterir ama dün salıncakta sallandın Helal olsun.'::text),
(298647,33183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezed általában mutatja az utat, de tegnap ... a hintán. Respekt.'::text,'hintáztál'::text,'hintázol'::text,NULL::text,'A kezed általában mutatja az utat, de tegnap hintáztál a hintán. Respekt.'::text),
(298650,33184,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein ruhiger kleiner Spaziergang, klar. Seine Hand ... mich die Terrassen hinauf.'::text,'zieht'::text,'zieht'::text,'zieht'::text,'Ein ruhiger kleiner Spaziergang, klar. Seine Hand zieht mich die Terrassen hinauf.'::text),
(298654,33184,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спокійна маленька прогулянка, авжеж. Його рука ... мене вгору терасами.'::text,'тягне'::text,'тягне'::text,'тягне'::text,'Спокійна маленька прогулянка, авжеж. Його рука тягне мене вгору терасами.'::text),
(298653,33184,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un paseíto tranquilo, obviamente. Su mano ... de mí terrazas arriba.'::text,'está tirando'::text,'tira'::text,'está tirando'::text,'Un paseíto tranquilo, obviamente. Su mano está tirando de mí terrazas arriba.'::text),
(298652,33184,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une petite balade tranquille, évidemment. Sa main ... en haut des terrasses.'::text,'est en train de me tirer'::text,'me tire'::text,'est en train de me tirer'::text,'Une petite balade tranquille, évidemment. Sa main est en train de me tirer en haut des terrasses.'::text),
(298655,33184,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin bir yürüyüş, tabii. Eli beni teraslardan yukarı ...'::text,'çekiyor'::text,'çeker'::text,'çekiyor'::text,'Sakin bir yürüyüş, tabii. Eli beni teraslardan yukarı çekiyor.'::text),
(298656,33184,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugis kis séta, persze. A keze ... engem fel a teraszokon.'::text,'húz'::text,'húz'::text,'húz'::text,'Nyugis kis séta, persze. A keze húz engem fel a teraszokon.'::text),
(298659,33185,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Plan. Normalerweise macht er ein Nickerchen, aber jetzt ... mich seine Hand bergauf.'::text,'zieht'::text,'zieht'::text,NULL::text,'Toller Plan. Normalerweise macht er ein Nickerchen, aber jetzt zieht mich seine Hand bergauf.'::text),
(298663,33185,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план. Зазвичай він дрімає, а зараз його рука ... мене вгору.'::text,'тягне'::text,'тягне'::text,NULL::text,'Чудовий план. Зазвичай він дрімає, а зараз його рука тягне мене вгору.'::text),
(298662,33185,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan. Normalmente se echa la siesta, pero ahora su mano ... de mí cuesta arriba.'::text,'está tirando'::text,'tira'::text,NULL::text,'Gran plan. Normalmente se echa la siesta, pero ahora su mano está tirando de mí cuesta arriba.'::text),
(298661,33185,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan. D''habitude il fait la sieste, mais là sa main ... vers le haut de la colline.'::text,'est en train de me tirer'::text,'me tire'::text,NULL::text,'Super plan. D''habitude il fait la sieste, mais là sa main est en train de me tirer vers le haut de la colline.'::text),
(298664,33185,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plan. Genelde şekerleme yapar ama şimdi eli beni yokuş yukarı ...'::text,'çekiyor'::text,'çeker'::text,NULL::text,'Harika plan. Genelde şekerleme yapar ama şimdi eli beni yokuş yukarı çekiyor.'::text),
(298665,33185,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek terv. Általában szunyókál, de most a keze ... engem felfelé a dombon.'::text,'húz'::text,'húz'::text,NULL::text,'Remek terv. Általában szunyókál, de most a keze húz engem felfelé a dombon.'::text),
(298668,33186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, nimm meine Hand. Ich ... dich hochziehen, ehrlich.'::text,'werde'::text,'werde'::text,'ziehend'::text,'Nee Bro, nimm meine Hand. Ich werde dich hochziehen, ehrlich.'::text),
(298672,33186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, тримай мою руку. Я ... тебе нагору, чесно.'::text,'витягну'::text,'витягну'::text,'витягуючи'::text,'Не, бро, тримай мою руку. Я витягну тебе нагору, чесно.'::text),
(298671,33186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, dame la mano. ... de ti hacia arriba, en serio.'::text,'Tiraré'::text,'Tiraré'::text,'Tirando'::text,'Qué va, tío, dame la mano. Tiraré de ti hacia arriba, en serio.'::text),
(298670,33186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, prends ma main. Je te ... vers le haut, sérieux.'::text,'tirerai'::text,'tirerai'::text,'tirant'::text,'Non frère, prends ma main. Je te tirerai vers le haut, sérieux.'::text),
(298673,33186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, elimi tut. Seni yukarı ..., cidden.'::text,'çekeceğim'::text,'çekeceğim'::text,'çekerek'::text,'Yok kanka, elimi tut. Seni yukarı çekeceğim, cidden.'::text),
(298674,33186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, fogd meg a kezem. Én ... téged, komolyan.'::text,'fel foglak húzni'::text,'fel foglak húzni'::text,'húzva'::text,'Á, tesó, fogd meg a kezem. Én fel foglak húzni téged, komolyan.'::text),
(298686,33188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap für Freitag: Seine Hand ... die Kamera zum Tempel führen.'::text,'wird'::text,'wird'::text,NULL::text,'Roadmap für Freitag: Seine Hand wird die Kamera zum Tempel führen.'::text),
(298690,33188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорожня карта на п''ятницю: його рука ... камеру до храму.'::text,'збирається повести'::text,'поведе'::text,NULL::text,'Дорожня карта на п''ятницю: його рука збирається повести камеру до храму.'::text),
(298689,33188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta para el viernes: su mano ... la cámara hasta el templo.'::text,'va a llevar'::text,'llevará'::text,NULL::text,'Hoja de ruta para el viernes: su mano va a llevar la cámara hasta el templo.'::text),
(298688,33188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feuille de route pour vendredi : sa main ... la caméra jusqu''au temple.'::text,'va mener'::text,'mènera'::text,NULL::text,'Feuille de route pour vendredi : sa main va mener la caméra jusqu''au temple.'::text),
(298691,33188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuma yol haritası: eli kamerayı tapınağa ...'::text,'götürecek'::text,'götürecek'::text,NULL::text,'Cuma yol haritası: eli kamerayı tapınağa götürecek.'::text),
(298692,33188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pénteki ütemterv: a keze ... a kamerát a templomhoz.'::text,'fogja vezetni'::text,'fogja vezetni'::text,NULL::text,'Pénteki ütemterv: a keze fogja vezetni a kamerát a templomhoz.'::text),
(298695,33189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er trägt viele ... aus Perlen an der Hand.'::text,'Armbänder'::text,'Schmuck'::text,'Armband'::text,'Er trägt viele Armbänder aus Perlen an der Hand.'::text),
(298699,33189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він носить на руці багато ... з намистин.'::text,'браслетів'::text,'прикрас'::text,'браслета'::text,'Він носить на руці багато браслетів з намистин.'::text),
(298698,33189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lleva muchas ... de cuentas en la mano.'::text,'pulseras'::text,'bisutería'::text,'pulsera'::text,'Lleva muchas pulseras de cuentas en la mano.'::text),
(298697,33189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il porte beaucoup de ... de perles à la main.'::text,'bracelets'::text,'bijoux'::text,'bracelet'::text,'Il porte beaucoup de bracelets de perles à la main.'::text),
(298700,33189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elinde çok sayıda boncuklu ... takıyor.'::text,'bilezik'::text,'takı'::text,'bilezik'::text,'Elinde çok sayıda boncuklu bilezik takıyor.'::text),
(298701,33189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sok gyöngyös ... hord a kezén.'::text,'karkötőt'::text,'ékszert'::text,'karkötőt'::text,'Sok gyöngyös karkötőt hord a kezén.'::text),
(307002,34112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, jeder in diesem Büro ... eine Erkältung. Ich muss los.'::text,'hat'::text,'haben'::text,'ist'::text,'Nee, jeder in diesem Büro hat eine Erkältung. Ich muss los.'::text),
(307006,34112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, в цьому офісі кожен ... застуду. Мушу бігти.'::text,'має'::text,'мати'::text,'є'::text,'Не, в цьому офісі кожен має застуду. Мушу бігти.'::text),
(307005,34112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, todo el mundo en esta oficina ... un resfriado. Me piro.'::text,'tiene'::text,'tienen'::text,'está'::text,'Qué va, todo el mundo en esta oficina tiene un resfriado. Me piro.'::text),
(307004,34112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, tout le monde dans ce bureau ... un rhume. Faut que j''y aille.'::text,'a'::text,'ont'::text,'est'::text,'Non, tout le monde dans ce bureau a un rhume. Faut que j''y aille.'::text),
(307007,34112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu ofisteki herkesin nezlesi ..., kaçmam lazım.'::text,'var'::text,'var'::text,NULL::text,'Yok, bu ofisteki herkesin nezlesi var, kaçmam lazım.'::text),
(307008,34112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, ebben az irodában mindenkinek ... nátha. Mennem kell.'::text,'van'::text,'van'::text,'van'::text,'Nem, ebben az irodában mindenkinek van nátha. Mennem kell.'::text),
(307011,34113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, dieses ganze Büro ... den ganzen Tag, ich werd noch krank.'::text,'hustet'::text,'husten'::text,'hustend'::text,'Ey, dieses ganze Büro hustet den ganzen Tag, ich werd noch krank.'::text),
(307015,34113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, увесь цей офіс ... цілий день, я точно захворію.'::text,'кашляє'::text,'кашляти'::text,'кашляючи'::text,'Йо, увесь цей офіс кашляє цілий день, я точно захворію.'::text),
(307014,34113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, toda esta oficina ... todo el día, me voy a poner malo.'::text,'tose'::text,'toser'::text,'tosiendo'::text,'Tío, toda esta oficina tose todo el día, me voy a poner malo.'::text),
(307013,34113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, tout ce bureau ... toute la journée, je vais tomber malade.'::text,'tousse'::text,'tousser'::text,'toussant'::text,'Wesh, tout ce bureau tousse toute la journée, je vais tomber malade.'::text),
(307016,34113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün ofis gün boyu ..., hasta olacağım.'::text,'öksürür'::text,'öksürmek'::text,'öksürerek'::text,'Kanka, bütün ofis gün boyu öksürür, hasta olacağım.'::text),
(307017,34113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ez az egész iroda egész nap ..., meg fogok betegedni.'::text,'köhög'::text,'köhögni'::text,'köhögő'::text,'Figyu, ez az egész iroda egész nap köhög, meg fogok betegedni.'::text),
(307029,34115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Büro hat viele ..., also gibt es viele Schreibtische.'::text,'Schreibtische'::text,'Schreibtisch'::text,'Schreibtische'::text,'Das Büro hat viele Schreibtische, also gibt es viele Schreibtische.'::text),
(307033,34115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В офісі багато ..., тож там багато столів.'::text,'столів'::text,'стіл'::text,'столів'::text,'В офісі багато столів, тож там багато столів.'::text),
(307032,34115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La oficina tiene muchos ..., así que hay muchos escritorios.'::text,'escritorios'::text,'escritorio'::text,'escritorios'::text,'La oficina tiene muchos escritorios, así que hay muchos escritorios.'::text),
(307031,34115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bureau a beaucoup de ..., donc il y a beaucoup de bureaux.'::text,'bureaux'::text,'bureau'::text,'bureaux'::text,'Le bureau a beaucoup de bureaux, donc il y a beaucoup de bureaux.'::text),
(307034,34115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofiste çok ... var, yani çok masa var.'::text,'masa'::text,'masa'::text,'masa'::text,'Ofiste çok masa var, yani çok masa var.'::text),
(307035,34115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodában sok ... van, tehát sok íróasztal van.'::text,'íróasztal'::text,'íróasztal'::text,'íróasztal'::text,'Az irodában sok íróasztal van, tehát sok íróasztal van.'::text),
(307038,34116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist eine Katastrophe! Im Büro sind ... Taschentücher mehr übrig!'::text,'keine'::text,'einige'::text,'viel'::text,'Das ist eine Katastrophe! Im Büro sind keine Taschentücher mehr übrig!'::text),
(307042,34116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це катастрофа! В офісі не залишилося ... серветок!'::text,'жодних'::text,'кілька'::text,'багато'::text,'Це катастрофа! В офісі не залишилося жодних серветок!'::text),
(307041,34116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esto es un desastre! ¡No queda ... pañuelo en la oficina!'::text,'ningún'::text,'algún'::text,'mucho'::text,'¡Esto es un desastre! ¡No queda ningún pañuelo en la oficina!'::text),
(307040,34116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est une catastrophe ! Il ne reste ... mouchoir au bureau !'::text,'aucun'::text,'des'::text,'beaucoup de'::text,'C''est une catastrophe ! Il ne reste aucun mouchoir au bureau !'::text),
(307043,34116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu bir felaket! Ofiste ... mendil kalmadı!'::text,'hiç'::text,'birkaç'::text,'çok'::text,'Bu bir felaket! Ofiste hiç mendil kalmadı!'::text),
(307044,34116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez katasztrófa! Nem maradt ... papír zsebkendő az irodában!'::text,'semmilyen'::text,'néhány'::text,'sok'::text,'Ez katasztrófa! Nem maradt semmilyen papír zsebkendő az irodában!'::text),
(307047,34117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Büro ... fünf kranke Leute.'::text,'sind'::text,'ist'::text,'sein'::text,'Im Büro sind fünf kranke Leute.'::text),
(307051,34117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В офісі ... п''ятеро хворих людей.'::text,'є'::text,'є'::text,'бути'::text,'В офісі є п''ятеро хворих людей.'::text),
(307050,34117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinco personas enfermas en la oficina.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay cinco personas enfermas en la oficina.'::text),
(307049,34117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinq personnes malades au bureau.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a cinq personnes malades au bureau.'::text),
(307052,34117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofiste beş hasta kişi ...'::text,'var'::text,'var'::text,'olmak'::text,'Ofiste beş hasta kişi var.'::text),
(307053,34117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt beteg ember ... az irodában.'::text,'van'::text,'van'::text,'lenni'::text,'Öt beteg ember van az irodában.'::text),
(307065,34119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, Büro. Nächstes Mal ... kranke Leute zu Hause bleiben.'::text,'sollten'::text,'sollten'::text,'sollen'::text,'Super gemacht, Büro. Nächstes Mal sollten kranke Leute zu Hause bleiben.'::text),
(307069,34119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, офісе. Наступного разу хворі люди ... залишитися вдома.'::text,'мали б'::text,'мали б'::text,'будуть'::text,'Чудова робота, офісе. Наступного разу хворі люди мали б залишитися вдома.'::text),
(307068,34119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, oficina. La próxima vez, los enfermos ... quedarse en casa.'::text,'deberían'::text,'deberían'::text,'deberán'::text,'Buen trabajo, oficina. La próxima vez, los enfermos deberían quedarse en casa.'::text),
(307067,34119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, le bureau. La prochaine fois, les malades ... rester chez eux.'::text,'devraient'::text,'devraient'::text,'devront'::text,'Bravo, le bureau. La prochaine fois, les malades devraient rester chez eux.'::text),
(307070,34119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aferin, ofis. Bir dahaki sefere hasta olanlar evde ...'::text,'kalmalı'::text,'kalmalı'::text,'kalacak'::text,'Aferin, ofis. Bir dahaki sefere hasta olanlar evde kalmalı.'::text),
(307071,34119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, iroda. Legközelebb a betegeknek otthon ... maradniuk.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Szép munka, iroda. Legközelebb a betegeknek otthon kellene maradniuk.'::text),
(307083,34121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kontrolliert Pässe. Er ist ... Beamter an der Grenze, kein Tourist.'::text,'ein'::text,'ein'::text,'der'::text,'Er kontrolliert Pässe. Er ist ein Beamter an der Grenze, kein Tourist.'::text),
(307087,34121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він перевіряє паспорти. Він ... офіцер на кордоні, а не турист.'::text,''::text,NULL::text,NULL::text,'Він перевіряє паспорти. Він офіцер на кордоні, а не турист.'::text),
(307086,34121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Revisa pasaportes. Es ... agente en la frontera, no un turista.'::text,'un'::text,'un'::text,'el'::text,'Revisa pasaportes. Es un agente en la frontera, no un turista.'::text),
(307085,34121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il contrôle les passeports. C''est ... agent à la frontière, pas un touriste.'::text,'un'::text,'un'::text,'l'''::text,'Il contrôle les passeports. C''est un agent à la frontière, pas un touriste.'::text),
(307088,34121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasaport kontrol ediyor. O sınırda ... memur, turist değil.'::text,'bir'::text,'bir'::text,NULL::text,'Pasaport kontrol ediyor. O sınırda bir memur, turist değil.'::text),
(307089,34121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Útleveleket ellenőriz. Ő ... tiszt a határon, nem turista.'::text,'egy'::text,'egy'::text,'a'::text,'Útleveleket ellenőriz. Ő egy tiszt a határon, nem turista.'::text),
(307101,34123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte leuchtet mit ... Taschenlampe in den Koffer.'::text,'seiner'::text,'ihrer'::text,'seiner'::text,'Der Beamte leuchtet mit seiner Taschenlampe in den Koffer.'::text),
(307105,34123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер світить ... ліхтариком у валізу.'::text,'своїм'::text,'своїм'::text,'своїм'::text,'Офіцер світить своїм ліхтариком у валізу.'::text),
(307104,34123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agente ilumina la maleta con ... linterna.'::text,'su'::text,'su'::text,'su'::text,'El agente ilumina la maleta con su linterna.'::text),
(307103,34123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent éclaire la valise avec ... lampe de poche.'::text,'sa'::text,'sa'::text,'sa'::text,'L''agent éclaire la valise avec sa lampe de poche.'::text),
(307106,34123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur ... el fenerini bavula tutuyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Memur onun el fenerini bavula tutuyor.'::text),
(307107,34123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt belevilágít a ... a bőröndbe.'::text,'zseblámpájával'::text,'zseblámpájával'::text,'zseblámpájával'::text,'A tiszt belevilágít a zseblámpájával a bőröndbe.'::text),
(307110,34124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist der Beamte unter dem Van? Weil er dort liegt.'::text,'Warum'::text,'Wo'::text,'Wer'::text,'Warum ist der Beamte unter dem Van? Weil er dort liegt.'::text),
(307114,34124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... офіцер під фургоном? Бо він там лежить.'::text,'Чому'::text,'Де'::text,'Хто'::text,'Чому офіцер під фургоном? Бо він там лежить.'::text),
(307113,34124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está el agente debajo de la furgoneta? Porque está tumbado ahí.'::text,'Por qué'::text,'Dónde'::text,'Quién'::text,'¿Por qué está el agente debajo de la furgoneta? Porque está tumbado ahí.'::text),
(307112,34124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''agent est-il sous le van ? Parce qu''il est allongé là.'::text,'Pourquoi'::text,'Où'::text,'Qui'::text,'Pourquoi l''agent est-il sous le van ? Parce qu''il est allongé là.'::text),
(307115,34124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur ... minibüsün altında? Çünkü orada yatıyor.'::text,'neden'::text,'nerede'::text,'kim'::text,'Memur neden minibüsün altında? Çünkü orada yatıyor.'::text),
(307116,34124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a tiszt a furgon alatt? Mert ott fekszik.'::text,'Miért'::text,'Hol'::text,'Ki'::text,'Miért van a tiszt a furgon alatt? Mert ott fekszik.'::text),
(307119,34125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte liegt ... der Straße unter dem Van! Total verrückt!'::text,'auf'::text,'in'::text,'an'::text,'Der Beamte liegt auf der Straße unter dem Van! Total verrückt!'::text),
(307123,34125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер лежить ... дорозі під фургоном! Просто божевілля!'::text,'на'::text,'в'::text,'біля'::text,'Офіцер лежить на дорозі під фургоном! Просто божевілля!'::text),
(307122,34125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El agente está tumbado ... la carretera debajo de la furgoneta! ¡Una locura total!'::text,'en'::text,'en'::text,'a'::text,'¡El agente está tumbado en la carretera debajo de la furgoneta! ¡Una locura total!'::text),
(307121,34125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent est allongé ... la route sous le van ! Complètement fou !'::text,'sur'::text,'dans'::text,'à'::text,'L''agent est allongé sur la route sous le van ! Complètement fou !'::text),
(307124,34125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur minibüsün altında yolun ... yatıyor! Resmen çılgınlık!'::text,'üstünde'::text,'içinde'::text,NULL::text,'Memur minibüsün altında yolun üstünde yatıyor! Resmen çılgınlık!'::text),
(307125,34125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt a furgon alatt fekszik az ...! Teljesen őrült!'::text,'úton'::text,'útban'::text,'útnál'::text,'A tiszt a furgon alatt fekszik az úton! Teljesen őrült!'::text),
(307128,34126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist das Schlimmste! Der Beamte holt ... gefaltete Hemden heraus!'::text,'zwei'::text,'zweite'::text,'Zweien'::text,'Das ist das Schlimmste! Der Beamte holt zwei gefaltete Hemden heraus!'::text),
(307132,34126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це найгірше! Офіцер дістає ... складені сорочки!'::text,'дві'::text,'другі'::text,'двійки'::text,'Це найгірше! Офіцер дістає дві складені сорочки!'::text),
(307131,34126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esto es lo peor! ¡El agente saca ... camisas dobladas!'::text,'dos'::text,'segundas'::text,'dos'::text,'¡Esto es lo peor! ¡El agente saca dos camisas dobladas!'::text),
(307130,34126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le pire ! L''agent sort ... chemises pliées !'::text,'deux'::text,'deuxièmes'::text,'deux'::text,'C''est le pire ! L''agent sort deux chemises pliées !'::text),
(307133,34126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu en kötüsü! Memur ... katlanmış gömlek çıkarıyor!'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Bu en kötüsü! Memur iki katlanmış gömlek çıkarıyor!'::text),
(307134,34126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a legrosszabb! A tiszt ... összehajtott inget vesz elő!'::text,'két'::text,'második'::text,'kettesek'::text,'Ez a legrosszabb! A tiszt két összehajtott inget vesz elő!'::text),
(307146,34128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend sitzt der Beamte normalerweise, aber gestern ... er unter einem Van.'::text,'lag'::text,'liegt'::text,NULL::text,'Mädel, anscheinend sitzt der Beamte normalerweise, aber gestern lag er unter einem Van.'::text),
(307150,34128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, офіцер зазвичай сидить, але вчора ... під фургоном.'::text,'лежав'::text,'лежить'::text,NULL::text,'Подруго, кажуть, офіцер зазвичай сидить, але вчора лежав під фургоном.'::text),
(307149,34128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el agente normalmente está sentado, pero ayer ... debajo de una furgoneta.'::text,'estuvo tumbado'::text,'está tumbado'::text,NULL::text,'Tía, al parecer el agente normalmente está sentado, pero ayer estuvo tumbado debajo de una furgoneta.'::text),
(307148,34128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment l''agent est d''habitude assis, mais hier il ... sous un van.'::text,'était allongé'::text,'est allongé'::text,NULL::text,'Ma belle, apparemment l''agent est d''habitude assis, mais hier il était allongé sous un van.'::text),
(307151,34128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan memur genelde oturur ama dün bir minibüsün altında ...'::text,'yattı'::text,'yatar'::text,NULL::text,'Kızım, anlaşılan memur genelde oturur ama dün bir minibüsün altında yattı.'::text),
(307152,34128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a tiszt általában ül, de tegnap egy furgon alatt ...'::text,'feküdt'::text,'fekszik'::text,NULL::text,'Csajszi, állítólag a tiszt általában ül, de tegnap egy furgon alatt feküdt.'::text),
(299964,33330,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So ein entspannter Sonntag, klar. Kämpfer ... den Hügel hinunter auf uns zu.'::text,'rennen'::text,'rennen'::text,'rennt'::text,'So ein entspannter Sonntag, klar. Kämpfer rennen den Hügel hinunter auf uns zu.'::text),
(299968,33330,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Така розслаблена неділя, авжеж. Воїни ... з пагорба прямо на нас.'::text,'біжать'::text,'біжать'::text,'біжить'::text,'Така розслаблена неділя, авжеж. Воїни біжать з пагорба прямо на нас.'::text),
(299967,33330,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué domingo tan relajante, obviamente. Unos guerreros ... colina abajo hacia nosotros.'::text,'están corriendo'::text,'corren'::text,'está corriendo'::text,'Qué domingo tan relajante, obviamente. Unos guerreros están corriendo colina abajo hacia nosotros.'::text),
(299966,33330,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un dimanche tellement reposant, évidemment. Des combattants ... la colline vers nous.'::text,'sont en train de dévaler'::text,'dévalent'::text,'est en train de dévaler'::text,'Un dimanche tellement reposant, évidemment. Des combattants sont en train de dévaler la colline vers nous.'::text),
(299969,33330,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kadar dinlendirici bir pazar, tabii. Savaşçılar tepeden aşağı bize doğru ...'::text,'koşuyor'::text,'koşar'::text,'koşuyor'::text,'Ne kadar dinlendirici bir pazar, tabii. Savaşçılar tepeden aşağı bize doğru koşuyor.'::text),
(299970,33330,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda pihentető vasárnap, persze. Harcosok ... le a dombról felénk.'::text,'rohannak'::text,'rohannak'::text,'rohan'::text,'Micsoda pihentető vasárnap, persze. Harcosok rohannak le a dombról felénk.'::text),
(299973,33331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makelloser Picknickhügel. Normalerweise laufen hier Schafe, aber heute ... Kämpfer herunter.'::text,'rennen'::text,'rennen'::text,NULL::text,'Makelloser Picknickhügel. Normalerweise laufen hier Schafe, aber heute rennen Kämpfer herunter.'::text),
(299977,33331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний пагорб для пікніка. Зазвичай тут ходять вівці, а сьогодні воїни ... вниз.'::text,'біжать'::text,'біжать'::text,NULL::text,'Бездоганний пагорб для пікніка. Зазвичай тут ходять вівці, а сьогодні воїни біжать вниз.'::text),
(299976,33331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Colina de pícnic impecable. Normalmente aquí pasean ovejas, pero hoy unos guerreros ... cuesta abajo.'::text,'están corriendo'::text,'corren'::text,NULL::text,'Colina de pícnic impecable. Normalmente aquí pasean ovejas, pero hoy unos guerreros están corriendo cuesta abajo.'::text),
(299975,33331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Colline de pique-nique parfaite. D''habitude, des moutons se promènent ici, mais aujourd''hui des combattants ... la pente.'::text,'sont en train de dévaler'::text,'dévalent'::text,NULL::text,'Colline de pique-nique parfaite. D''habitude, des moutons se promènent ici, mais aujourd''hui des combattants sont en train de dévaler la pente.'::text),
(299978,33331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz piknik tepesi. Genelde burada koyunlar yürür ama bugün savaşçılar aşağı ...'::text,'koşuyor'::text,'koşar'::text,NULL::text,'Kusursuz piknik tepesi. Genelde burada koyunlar yürür ama bugün savaşçılar aşağı koşuyor.'::text),
(299979,33331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan piknikdomb. Itt általában birkák sétálnak, de ma harcosok ... lefelé.'::text,'rohannak'::text,'rohannak'::text,NULL::text,'Hibátlan piknikdomb. Itt általában birkák sétálnak, de ma harcosok rohannak lefelé.'::text),
(299982,33332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chill, Bro, sie ... am Fuß des Hügels anhalten, ehrlich.'::text,'werden'::text,'werden'::text,'anhaltend'::text,'Chill, Bro, sie werden am Fuß des Hügels anhalten, ehrlich.'::text),
(299986,33332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслабся, бро, вони ... біля підніжжя пагорба, чесно.'::text,'зупиняться'::text,'зупиняться'::text,'зупиняючись'::text,'Розслабся, бро, вони зупиняться біля підніжжя пагорба, чесно.'::text),
(299985,33332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tranqui, tío, ... al pie de la colina, en serio.'::text,'pararán'::text,'pararán'::text,'parando'::text,'Tranqui, tío, pararán al pie de la colina, en serio.'::text),
(299984,33332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Détends-toi frère, ils ... au pied de la colline, sérieux.'::text,'s''arrêteront'::text,'s''arrêteront'::text,'s''arrêtant'::text,'Détends-toi frère, ils s''arrêteront au pied de la colline, sérieux.'::text),
(299987,33332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat ol kanka, tepenin eteğinde ..., cidden.'::text,'duracaklar'::text,'duracaklar'::text,'durarak'::text,'Rahat ol kanka, tepenin eteğinde duracaklar, cidden.'::text),
(299988,33332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugi, tesó, a domb lábánál ..., komolyan.'::text,'meg fognak állni'::text,'meg fognak állni'::text,'megállva'::text,'Nyugi, tesó, a domb lábánál meg fognak állni, komolyan.'::text),
(299991,33333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kämpfer haben einen Plan. Sie ... mittags den Hügel hinunterrennen.'::text,'werden'::text,'wird'::text,'werden'::text,'Die Kämpfer haben einen Plan. Sie werden mittags den Hügel hinunterrennen.'::text),
(299995,33333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Воїни мають план. Вони ... з пагорба опівдні.'::text,'збираються збігти'::text,'збирається збігти'::text,'збираються збігти'::text,'Воїни мають план. Вони збираються збігти з пагорба опівдні.'::text),
(299994,33333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los guerreros tienen un plan. ... colina abajo a mediodía.'::text,'Van a correr'::text,'Va a correr'::text,'Van a correr'::text,'Los guerreros tienen un plan. Van a correr colina abajo a mediodía.'::text),
(299993,33333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les combattants ont un plan. Ils ... la colline à midi.'::text,'vont dévaler'::text,'va dévaler'::text,'vont dévaler'::text,'Les combattants ont un plan. Ils vont dévaler la colline à midi.'::text),
(299996,33333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Savaşçıların bir planı var. Öğlen tepeden aşağı ...'::text,'koşacaklar'::text,'koşacak'::text,'koşacaklar'::text,'Savaşçıların bir planı var. Öğlen tepeden aşağı koşacaklar.'::text),
(299997,33333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A harcosoknak van egy tervük. Délben le ... rohanni a dombról.'::text,'fognak'::text,'fog'::text,'fognak'::text,'A harcosoknak van egy tervük. Délben le fognak rohanni a dombról.'::text),
(300009,33335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, auf dem Hügel war so viel ...'::text,'Lärm'::text,'Lärm'::text,'Geräusche'::text,'Mädel, ich hab gehört, auf dem Hügel war so viel Lärm.'::text),
(300013,33335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що на тому пагорбі було стільки ...'::text,'шуму'::text,'шумів'::text,'звуків'::text,'Подруго, я чула, що на тому пагорбі було стільки шуму.'::text),
(300012,33335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que en esa colina había muchísimo ...'::text,'ruido'::text,'ruido'::text,'sonidos'::text,'Tía, me han dicho que en esa colina había muchísimo ruido.'::text),
(300011,33335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu qu''il y avait tellement de ... sur cette colline.'::text,'bruit'::text,'bruit'::text,'sons'::text,'Ma belle, j''ai entendu qu''il y avait tellement de bruit sur cette colline.'::text),
(300014,33335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o tepede çok fazla ... olduğunu duydum.'::text,'gürültü'::text,'gürültüler'::text,'sesler'::text,'Kızım, o tepede çok fazla gürültü olduğunu duydum.'::text),
(300015,33335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy olyan nagy ... volt azon a dombon.'::text,'zaj'::text,'zaj'::text,'hangok'::text,'Csajszi, azt hallottam, hogy olyan nagy zaj volt azon a dombon.'::text),
(300018,33336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt. Du rennst mit ... Energie den Hügel runter.'::text,'so viel'::text,'so vielen'::text,'ein paar'::text,'Respekt. Du rennst mit so viel Energie den Hügel runter.'::text),
(300022,33336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект. Ти збігаєш із того пагорба, маючи ... енергії.'::text,'стільки'::text,'стільки'::text,'кілька'::text,'Респект. Ти збігаєш із того пагорба, маючи стільки енергії.'::text),
(300021,33336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mis respetos. Bajas corriendo esa colina con ... energía.'::text,'tanta'::text,'tantas'::text,'unas pocas'::text,'Mis respetos. Bajas corriendo esa colina con tanta energía.'::text),
(300020,33336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect. Tu dévales cette colline avec ... d''énergie.'::text,'tellement'::text,'tellement'::text,'un peu'::text,'Respect. Tu dévales cette colline avec tellement d''énergie.'::text),
(300023,33336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal olsun. O tepeden ... enerjiyle koşarak iniyorsun.'::text,'o kadar çok'::text,'o kadar çok'::text,'birkaç'::text,'Helal olsun. O tepeden o kadar çok enerjiyle koşarak iniyorsun.'::text),
(300024,33336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt. ... energiával rohansz le arról a dombról.'::text,'Annyi'::text,'Annyi'::text,'Pár'::text,'Respekt. Annyi energiával rohansz le arról a dombról.'::text),
(300027,33337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, auf deinem Hügel ... so viele Flaggen. Ikonisch.'::text,'sind'::text,'ist'::text,'sein'::text,'Ehrlich gesagt, auf deinem Hügel sind so viele Flaggen. Ikonisch.'::text),
(300031,33337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, на твоєму пагорбі ... стільки прапорів. Іконічно.'::text,'є'::text,'є'::text,'бути'::text,'Не брехатиму, на твоєму пагорбі є стільки прапорів. Іконічно.'::text),
(300030,33337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, en tu colina ... tantísimas banderas. Icónico.'::text,'hay'::text,'hay'::text,'hay'::text,'No voy a mentir, en tu colina hay tantísimas banderas. Icónico.'::text),
(300029,33337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, ... tellement de drapeaux sur ta colline. Iconique.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Je vais pas mentir, il y a tellement de drapeaux sur ta colline. Iconique.'::text),
(300032,33337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, tepende o kadar çok bayrak ..., resmen ikonik.'::text,'var'::text,'var'::text,'olmak'::text,'Yalan yok, tepende o kadar çok bayrak var, resmen ikonik.'::text),
(300033,33337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, annyi zászló ... a dombodon. Ikonikus.'::text,'van'::text,'van'::text,'lenni'::text,'Nem fogok hazudni, annyi zászló van a dombodon. Ikonikus.'::text),
(301413,33491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, der Waschsalon ... ein schweres Dampfbügeleisen, muss man sagen.'::text,'hat'::text,'haben'::text,'hat'::text,'Ey, der Waschsalon hat ein schweres Dampfbügeleisen, muss man sagen.'::text),
(301417,33491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, пральня ... важку парову праску, треба визнати.'::text,'має'::text,'мати'::text,'має'::text,'Йо, пральня має важку парову праску, треба визнати.'::text),
(301416,33491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la lavandería ... una plancha de vapor pesada, hay que decirlo.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, la lavandería tiene una plancha de vapor pesada, hay que decirlo.'::text),
(301415,33491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, la laverie ... un fer à vapeur bien lourd, faut l''avouer.'::text,'a'::text,'ont'::text,'a'::text,'Wesh, la laverie a un fer à vapeur bien lourd, faut l''avouer.'::text),
(301418,33491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çamaşırhanenin ağır bir buharlı ütüsü ..., kabul etmek lazım.'::text,'var'::text,'var'::text,'var'::text,'Kanka, çamaşırhanenin ağır bir buharlı ütüsü var, kabul etmek lazım.'::text),
(301419,33491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a mosodának ... egy nehéz gőzvasalója, azt meg kell hagyni.'::text,'van'::text,'van'::text,'van'::text,'Figyu, a mosodának van egy nehéz gőzvasalója, azt meg kell hagyni.'::text),
(301422,33492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... den ganzen Tag Hemden mit dem Bügeleisen. Das muss wehtun.'::text,'bügelt'::text,'bügeln'::text,'bügelnd'::text,'Alter, er bügelt den ganzen Tag Hemden mit dem Bügeleisen. Das muss wehtun.'::text),
(301426,33492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він цілий день ... сорочки праскою. Мабуть, боляче.'::text,'прасує'::text,'прасувати'::text,'прасуючи'::text,'Бро, він цілий день прасує сорочки праскою. Мабуть, боляче.'::text),
(301425,33492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... camisas con la plancha todo el día. Tiene que doler.'::text,'plancha'::text,'planchar'::text,'planchando'::text,'Tío, él plancha camisas con la plancha todo el día. Tiene que doler.'::text),
(301424,33492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... des chemises avec le fer toute la journée. Ça doit faire mal.'::text,'repasse'::text,'repasser'::text,'repassant'::text,'Frère, il repasse des chemises avec le fer toute la journée. Ça doit faire mal.'::text),
(301427,33492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün gün ütüyle gömlek ..., bu kesin acıtır.'::text,'ütüler'::text,'ütülemek'::text,'ütüleyerek'::text,'Kanka, bütün gün ütüyle gömlek ütüler, bu kesin acıtır.'::text),
(301428,33492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egész nap ... az ingeket a vasalóval. Ez fájhat.'::text,'vasalja'::text,'vasalni'::text,'vasaló'::text,'Tesó, egész nap vasalja az ingeket a vasalóval. Ez fájhat.'::text),
(301431,33493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Bügeleisen ist heiß, also ... er das Hemd bügeln.'::text,'kann'::text,'kann'::text,'kann'::text,'Das Bügeleisen ist heiß, also kann er das Hemd bügeln.'::text),
(301435,33493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Праска гаряча, тож він ... попрасувати сорочку.'::text,'може'::text,'може'::text,'може'::text,'Праска гаряча, тож він може попрасувати сорочку.'::text),
(301434,33493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plancha está caliente, así que ... planchar la camisa.'::text,'puede'::text,'puede'::text,'puede'::text,'La plancha está caliente, así que puede planchar la camisa.'::text),
(301433,33493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fer est chaud, alors il ... repasser la chemise.'::text,'peut'::text,'peut'::text,'peut'::text,'Le fer est chaud, alors il peut repasser la chemise.'::text),
(301436,33493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütü sıcak, bu yüzden gömleği ...'::text,'ütüleyebilir'::text,'ütüleyebilir'::text,'ütüleyebilir'::text,'Ütü sıcak, bu yüzden gömleği ütüleyebilir.'::text),
(301437,33493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vasaló forró, így ki ... vasalni az inget.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'A vasaló forró, így ki tudja vasalni az inget.'::text),
(301440,33494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit dem Bügeleisen bügelt er zwei ...'::text,'Hemden.'::text,'Hemd.'::text,'Hemden.'::text,'Mit dem Bügeleisen bügelt er zwei Hemden.'::text),
(301444,33494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Праскою він прасує дві ...'::text,'сорочки.'::text,'сорочка.'::text,'сорочки.'::text,'Праскою він прасує дві сорочки.'::text),
(301443,33494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con la plancha, él plancha dos ...'::text,'camisas.'::text,'camisa.'::text,'camisas.'::text,'Con la plancha, él plancha dos camisas.'::text),
(301442,33494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec le fer, il repasse deux ...'::text,'chemises.'::text,'chemise.'::text,'chemises.'::text,'Avec le fer, il repasse deux chemises.'::text),
(301445,33494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütüyle iki ... ütülüyor.'::text,'gömlek'::text,'gömlek'::text,'gömlek'::text,'Ütüyle iki gömlek ütülüyor.'::text),
(301446,33494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vasalóval két ... vasal ki.'::text,'inget'::text,'inget'::text,'inget'::text,'A vasalóval két inget vasal ki.'::text),
(301467,33497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... du nie ein heißes Bügeleisen auf einem Hemd liegen lassen.'::text,'solltest'::text,'solltest'::text,'sollst'::text,'Bestie, anscheinend solltest du nie ein heißes Bügeleisen auf einem Hemd liegen lassen.'::text),
(301471,33497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ти ніколи не ... залишати гарячу праску на сорочці.'::text,'мала б'::text,'мала б'::text,'будеш'::text,'Подруго, кажуть, ти ніколи не мала б залишати гарячу праску на сорочці.'::text),
(301470,33497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer nunca ... dejar una plancha caliente sobre una camisa.'::text,'deberías'::text,'deberías'::text,'deberás'::text,'Tía, al parecer nunca deberías dejar una plancha caliente sobre una camisa.'::text),
(301469,33497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment tu ne ... jamais laisser un fer chaud sur une chemise.'::text,'devrais'::text,'devrais'::text,'devras'::text,'Ma belle, apparemment tu ne devrais jamais laisser un fer chaud sur une chemise.'::text),
(301472,33497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anlaşılan sıcak ütüyü asla gömleğin üstünde ...'::text,'bırakmamalısın'::text,'bırakmamalısın'::text,'bırakmayacaksın'::text,'Kanka, anlaşılan sıcak ütüyü asla gömleğin üstünde bırakmamalısın.'::text),
