(322810,35868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Він ріже рибу так ..., що вона повністю зникає!'::text,'тонко'::text,'тонкий'::text,'тонкість'::text,'Ні! Він ріже рибу так тонко, що вона повністю зникає!'::text),
(322809,35868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Corta el pescado tan ... que desaparece por completo!'::text,'finamente'::text,'fino'::text,'finura'::text,'¡No! ¡Corta el pescado tan finamente que desaparece por completo!'::text),
(322808,35868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Il coupe le poisson si ... qu''il disparaît complètement !'::text,'finement'::text,'fin'::text,'finesse'::text,'Non ! Il coupe le poisson si finement qu''il disparaît complètement !'::text),
(322811,35868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Balığı o kadar ... kesiyor ki tamamen yok oluyor!'::text,'ince bir şekilde'::text,'ince'::text,'incelik'::text,'Hayır! Balığı o kadar ince bir şekilde kesiyor ki tamamen yok oluyor!'::text),
(322812,35868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Olyan ... vágja a halat, hogy teljesen eltűnik!'::text,'vékonyan'::text,'vékony'::text,'vékonyság'::text,'Ne! Olyan vékonyan vágja a halat, hogy teljesen eltűnik!'::text),
(322815,35869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Scheibe ist sehr dünn, ... bricht sie in seinen Händen!'::text,'also'::text,'weil'::text,'aber'::text,'Katastrophe! Die Scheibe ist sehr dünn, also bricht sie in seinen Händen!'::text),
(322819,35869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Скибочка дуже тонка, ... вона ламається в нього в руках!'::text,'тому'::text,'бо'::text,'але'::text,'Катастрофа! Скибочка дуже тонка, тому вона ламається в нього в руках!'::text),
(322818,35869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡La loncha es muy fina, ... se le rompe en las manos!'::text,'así que'::text,'porque'::text,'pero'::text,'¡Desastre! ¡La loncha es muy fina, así que se le rompe en las manos!'::text),
(322817,35869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! La tranche est très fine, ... elle se casse dans ses mains !'::text,'donc'::text,'parce qu'''::text,'mais'::text,'Catastrophe ! La tranche est très fine, donc elle se casse dans ses mains !'::text),
(322820,35869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Dilim çok ince ... elinde parçalanıyor!'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Felaket! Dilim çok ince bu yüzden elinde parçalanıyor!'::text),
(322821,35869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A szelet nagyon vékony, ... szétesik a kezében!'::text,'ezért'::text,'mert'::text,'de'::text,'Katasztrófa! A szelet nagyon vékony, ezért szétesik a kezében!'::text),
(302781,33643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schaut vom Grat auf ...'::text,'jene Landschaft'::text,'jene Landschaften'::text,'diese Landschaften'::text,'Sie schaut vom Grat auf jene Landschaft.'::text),
(302785,33643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дивиться з хребта на ...'::text,'той краєвид'::text,'той краєвид'::text,'цей краєвид'::text,'Вона дивиться з хребта на той краєвид.'::text),
(302784,33643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira ... desde la cresta.'::text,'ese paisaje'::text,'esos paisajes'::text,'estos paisajes'::text,'Mira ese paisaje desde la cresta.'::text),
(302783,33643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle regarde ... depuis la crête.'::text,'ce paysage'::text,'ces paysages'::text,'ces paysages'::text,'Elle regarde ce paysage depuis la crête.'::text),
(302786,33643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırttan ... bakıyor.'::text,'şu manzaraya'::text,'şu manzaraya'::text,'bu manzaraya'::text,'Sırttan şu manzaraya bakıyor.'::text),
(302787,33643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerincről nézi ...'::text,'azt a tájat'::text,'azokat a tájakat'::text,'ezeket a tájakat'::text,'A gerincről nézi azt a tájat.'::text),
(302790,33644,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau trägt ... Rucksack durch die Berglandschaft.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Die Frau trägt ihren Rucksack durch die Berglandschaft.'::text),
(302794,33644,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка несе ... рюкзак гірським краєвидом.'::text,'свій'::text,'свій'::text,'свій'::text,'Жінка несе свій рюкзак гірським краєвидом.'::text),
(302793,33644,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer lleva ... mochila por el paisaje de montaña.'::text,'su'::text,'su'::text,'su'::text,'La mujer lleva su mochila por el paisaje de montaña.'::text),
(302792,33644,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme porte ... sac à dos à travers le paysage de montagne.'::text,'son'::text,'son'::text,'son'::text,'La femme porte son sac à dos à travers le paysage de montagne.'::text),
(302795,33644,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın ... sırt çantasını dağ manzarası boyunca taşıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kadın onun sırt çantasını dağ manzarası boyunca taşıyor.'::text),
(302796,33644,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő a hegyi tájon át viszi a ...'::text,'hátizsákját'::text,'hátizsákját'::text,'hátizsákját'::text,'A nő a hegyi tájon át viszi a hátizsákját.'::text),
(302799,33645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... klettert sie hoch, um die Landschaft zu sehen? Weil sie schön ist.'::text,'Warum'::text,'Wo'::text,'Wer'::text,'Warum klettert sie hoch, um die Landschaft zu sehen? Weil sie schön ist.'::text),
(302803,33645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона піднімається, щоб побачити краєвид? Бо він гарний.'::text,'Чому'::text,'Куди'::text,'Хто'::text,'Чому вона піднімається, щоб побачити краєвид? Бо він гарний.'::text),
(302802,33645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... sube para ver el paisaje? Porque es precioso.'::text,'Por qué'::text,'Dónde'::text,'Quién'::text,'¿Por qué sube para ver el paisaje? Porque es precioso.'::text),
(302801,33645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... grimpe-t-elle pour voir le paysage ? Parce qu''il est beau.'::text,'Pourquoi'::text,'Où'::text,'Qui'::text,'Pourquoi grimpe-t-elle pour voir le paysage ? Parce qu''il est beau.'::text),
(302804,33645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Manzarayı görmek için ... tırmanıyor? Çünkü çok güzel.'::text,'neden'::text,'nereye'::text,'kim'::text,'Manzarayı görmek için neden tırmanıyor? Çünkü çok güzel.'::text),
(302805,33645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mászik fel, hogy lássa a tájat? Mert gyönyörű.'::text,'Miért'::text,'Hová'::text,'Ki'::text,'Miért mászik fel, hogy lássa a tájat? Mert gyönyörű.'::text),
(302817,33647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie reist ... Stunden für diese Landschaft! Absolut lohnenswert!'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Sie reist zehn Stunden für diese Landschaft! Absolut lohnenswert!'::text),
(302821,33647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона їде ... годин заради цього краєвиду! Воно того варте!'::text,'десять'::text,'десяту'::text,'десятки'::text,'Вона їде десять годин заради цього краєвиду! Воно того варте!'::text),
(302820,33647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Viaja ... horas por este paisaje! ¡Merece totalmente la pena!'::text,'diez'::text,'décimas'::text,'diez'::text,'¡Viaja diez horas por este paisaje! ¡Merece totalmente la pena!'::text),
(302819,33647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle voyage ... heures pour ce paysage ! Ça vaut totalement le coup !'::text,'dix'::text,'dixièmes'::text,'dix'::text,'Elle voyage dix heures pour ce paysage ! Ça vaut totalement le coup !'::text),
(302822,33647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu manzara için ... saat yolculuk ediyor! Kesinlikle değer!'::text,'on'::text,'onuncu'::text,'onlar'::text,'Bu manzara için on saat yolculuk ediyor! Kesinlikle değer!'::text),
(302823,33647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... órát utazik ezért a tájért! Abszolút megéri!'::text,'Tíz'::text,'Tizedik'::text,'Tízesek'::text,'Tíz órát utazik ezért a tájért! Abszolút megéri!'::text),
(302835,33649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, anscheinend fährt sie normalerweise, aber gestern ... sie für diese Landschaft.'::text,'wanderte'::text,'wandert'::text,NULL::text,'Also, anscheinend fährt sie normalerweise, aber gestern wanderte sie für diese Landschaft.'::text),
(302839,33649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, вона зазвичай їздить, але вчора ... заради того краєвиду.'::text,'пішла в похід'::text,'ходить у походи'::text,NULL::text,'Короче, кажуть, вона зазвичай їздить, але вчора пішла в похід заради того краєвиду.'::text),
(302838,33649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer normalmente va en transporte, pero ayer ... por ese paisaje.'::text,'hizo senderismo'::text,'hace senderismo'::text,NULL::text,'Vale, pues al parecer normalmente va en transporte, pero ayer hizo senderismo por ese paisaje.'::text),
(302837,33649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment d''habitude elle prend les transports, mais hier elle ... pour ce paysage.'::text,'a randonné'::text,'randonne'::text,NULL::text,'Bon, apparemment d''habitude elle prend les transports, mais hier elle a randonné pour ce paysage.'::text),
(302840,33649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan genelde araçla gider ama dün o manzara için ...'::text,'yürüyüş yaptı'::text,'yürüyüş yapar'::text,NULL::text,'Tamam, anlaşılan genelde araçla gider ama dün o manzara için yürüyüş yaptı.'::text),
(302841,33649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag általában járművel megy, de tegnap ... azért a tájért.'::text,'túrázott'::text,'túrázik'::text,NULL::text,'Szóval, állítólag általában járművel megy, de tegnap túrázott azért a tájért.'::text),
(302844,33650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jetzt vom Grat aus auf die Landschaft.'::text,'schaut'::text,'schaut'::text,'schaut'::text,'Sie schaut jetzt vom Grat aus auf die Landschaft.'::text),
(302848,33650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зараз ... на краєвид із хребта.'::text,'дивиться'::text,'дивиться'::text,'дивиться'::text,'Вона зараз дивиться на краєвид із хребта.'::text),
(302847,33650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... el paisaje desde la cresta.'::text,'está mirando'::text,'mira'::text,'está mirando'::text,'Ahora está mirando el paisaje desde la cresta.'::text),
(302846,33650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le paysage depuis la crête maintenant.'::text,'est en train de regarder'::text,'regarde'::text,'est en train de regarder'::text,'Elle est en train de regarder le paysage depuis la crête maintenant.'::text),
(302849,33650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi sırttan manzaraya ...'::text,'bakıyor'::text,'bakar'::text,'bakıyor'::text,'Şimdi sırttan manzaraya bakıyor.'::text),
(302850,33650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most a gerincről ... a tájat.'::text,'nézi'::text,'nézi'::text,'nézi'::text,'Most a gerincről nézi a tájat.'::text),
(301854,33540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise lässt sie den Tee ausfallen, aber heute ... sie Wasser im Wasserkocher für 5 Stakeholder.'::text,'kocht'::text,'kocht'::text,NULL::text,'Normalerweise lässt sie den Tee ausfallen, aber heute kocht sie Wasser im Wasserkocher für 5 Stakeholder.'::text),
(301858,33540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона пропускає чай, але сьогодні ... чайник для 5 стейкхолдерів.'::text,'кип''ятить'::text,'кип''ятить'::text,NULL::text,'Зазвичай вона пропускає чай, але сьогодні кип''ятить чайник для 5 стейкхолдерів.'::text),
(301857,33540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente pasa del té, pero hoy ... agua en el hervidor para 5 stakeholders.'::text,'está hirviendo'::text,'hierve'::text,NULL::text,'Normalmente pasa del té, pero hoy está hirviendo agua en el hervidor para 5 stakeholders.'::text),
(301856,33540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle zappe le thé, mais aujourd''hui elle ... la bouilloire pour 5 parties prenantes.'::text,'est en train de faire chauffer'::text,'fait chauffer'::text,NULL::text,'D''habitude elle zappe le thé, mais aujourd''hui elle est en train de faire chauffer la bouilloire pour 5 parties prenantes.'::text),
(301859,33540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde çayı atlar ama bugün 5 paydaş için su ...'::text,'kaynatıyor'::text,'kaynatır'::text,NULL::text,'Genelde çayı atlar ama bugün 5 paydaş için su kaynatıyor.'::text),
(301860,33540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában kihagyja a teát, de ma 5 stakeholdernek ... vizet a vízforralóban.'::text,'forral'::text,'forral'::text,NULL::text,'Általában kihagyja a teát, de ma 5 stakeholdernek forral vizet a vízforralóban.'::text),
(301863,33541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wasserkocher kocht, also ... das Wasser heiß sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Der Wasserkocher kocht, also wird das Wasser heiß sein.'::text),
(301867,33541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чайник кипить, тож вода ... гаряча.'::text,'буде'::text,'буде'::text,'буде'::text,'Чайник кипить, тож вода буде гаряча.'::text),
(301866,33541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hervidor está hirviendo, así que el agua ... caliente.'::text,'estará'::text,'estará'::text,'estará'::text,'El hervidor está hirviendo, así que el agua estará caliente.'::text),
(301865,33541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bouilloire bout, donc l''eau ... chaude.'::text,'sera'::text,'sera'::text,'sera'::text,'La bouilloire bout, donc l''eau sera chaude.'::text),
(301868,33541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su ısıtıcısı kaynıyor, yani su sıcak ...'::text,'olacak'::text,'olacak'::text,'olacak'::text,'Su ısıtıcısı kaynıyor, yani su sıcak olacak.'::text),
(301869,33541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forr a vízforraló, tehát a víz forró ...'::text,'lesz'::text,'lesz'::text,'lesz'::text,'Forr a vízforraló, tehát a víz forró lesz.'::text),
(301872,33542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fünf Becher sind bereit, also ... sie den Wasserkocher am Hahn füllen.'::text,'wird'::text,'werden'::text,'wird'::text,'Fünf Becher sind bereit, also wird sie den Wasserkocher am Hahn füllen.'::text),
(301876,33542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'П''ять кухлів готові, тож вона ... чайник під краном.'::text,'збирається наповнити'::text,'збираються наповнити'::text,'збирається наповнити'::text,'П''ять кухлів готові, тож вона збирається наповнити чайник під краном.'::text),
(301875,33542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cinco tazas están listas, así que ... el hervidor en el grifo.'::text,'va a llenar'::text,'van a llenar'::text,'va a llenar'::text,'Cinco tazas están listas, así que va a llenar el hervidor en el grifo.'::text),
(301874,33542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cinq mugs sont prêts, alors elle ... la bouilloire au robinet.'::text,'va remplir'::text,'vont remplir'::text,'va remplir'::text,'Cinq mugs sont prêts, alors elle va remplir la bouilloire au robinet.'::text),
(301877,33542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş kupa hazır, bu yüzden su ısıtıcısını musluktan ...'::text,'dolduracak'::text,'dolduracaklar'::text,'dolduracak'::text,'Beş kupa hazır, bu yüzden su ısıtıcısını musluktan dolduracak.'::text),
(301878,33542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt bögre készen áll, ezért a csapnál ... tölteni a vízforralót.'::text,'meg fogja'::text,'meg fogják'::text,'meg fogja'::text,'Öt bögre készen áll, ezért a csapnál meg fogja tölteni a vízforralót.'::text),
(301881,33543,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das rote Licht ist an und Dampf kommt heraus. Der Wasserkocher ...'::text,'wird kochen'::text,'wird kochen'::text,NULL::text,'Das rote Licht ist an und Dampf kommt heraus. Der Wasserkocher wird kochen.'::text),
(301885,33543,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний вогник світиться, і йде пара. Чайник ...'::text,'збирається закипіти'::text,'закипить'::text,NULL::text,'Червоний вогник світиться, і йде пара. Чайник збирається закипіти.'::text),
(301884,33543,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luz roja está encendida y sale vapor. El hervidor ...'::text,'va a hervir'::text,'hervirá'::text,NULL::text,'La luz roja está encendida y sale vapor. El hervidor va a hervir.'::text),
(301883,33543,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le voyant rouge est allumé et de la vapeur sort. La bouilloire ...'::text,'va bouillir'::text,'bouillira'::text,NULL::text,'Le voyant rouge est allumé et de la vapeur sort. La bouilloire va bouillir.'::text),
(301886,33543,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı ışık yanıyor ve buhar çıkıyor. Su ısıtıcısı ...'::text,'kaynayacak'::text,'kaynayacak'::text,NULL::text,'Kırmızı ışık yanıyor ve buhar çıkıyor. Su ısıtıcısı kaynayacak.'::text),
(301887,33543,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ég a piros lámpa, és jön a gőz. A vízforraló ...'::text,'forrni fog'::text,'forrni fog'::text,NULL::text,'Ég a piros lámpa, és jön a gőz. A vízforraló forrni fog.'::text),
(301890,33544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie meinte, sie hat so viel ... in den Wasserkocher gefüllt.'::text,'Wasser'::text,'Wasser'::text,'Tassen'::text,'Bestie, sie meinte, sie hat so viel Wasser in den Wasserkocher gefüllt.'::text),
(301894,33544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що налила в той чайник стільки ...'::text,'води'::text,'вод'::text,'чашок'::text,'Подруго, вона сказала, що налила в той чайник стільки води.'::text),
(301893,33544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dijo que echó muchísima ... en ese hervidor.'::text,'agua'::text,'agua'::text,'tazas'::text,'Tía, dijo que echó muchísima agua en ese hervidor.'::text),
(301892,33544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a dit qu''elle avait mis tellement ... dans cette bouilloire.'::text,'d''eau'::text,'d''eau'::text,'de tasses'::text,'Ma belle, elle a dit qu''elle avait mis tellement d''eau dans cette bouilloire.'::text),
(301895,33544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o su ısıtıcısına çok fazla ... koyduğunu söyledi.'::text,'su'::text,'sular'::text,'bardak'::text,'Kanka, o su ısıtıcısına çok fazla su koyduğunu söyledi.'::text),
(301896,33544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy annyi ... tett abba a vízforralóba.'::text,'vizet'::text,'vizet'::text,'csészét'::text,'Csajszi, azt mondta, hogy annyi vizet tett abba a vízforralóba.'::text),
(301899,33545,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal! Anscheinend hat sie nicht ... Milch, nur den Wasserkocher.'::text,'viel'::text,'viele'::text,'etwas'::text,'Rate mal! Anscheinend hat sie nicht viel Milch, nur den Wasserkocher.'::text),
(301903,33545,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви собі! Кажуть, у неї немає ... молока, лише чайник.'::text,'багато'::text,'багато'::text,'трохи'::text,'Уяви собі! Кажуть, у неї немає багато молока, лише чайник.'::text),
(301902,33545,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Al parecer no tiene ... leche, solo el hervidor.'::text,'mucha'::text,'muchas'::text,'algo de'::text,'¿Sabes qué? Al parecer no tiene mucha leche, solo el hervidor.'::text),
(301901,33545,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi ? Apparemment elle n''a pas ... lait, juste la bouilloire.'::text,'beaucoup de'::text,'beaucoup de'::text,'du'::text,'Devine quoi ? Apparemment elle n''a pas beaucoup de lait, juste la bouilloire.'::text),
(301904,33545,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu? Anlaşılan ... sütü yok, sadece su ısıtıcısı var.'::text,'çok'::text,'çok'::text,'biraz'::text,'Bil bakalım ne oldu? Anlaşılan çok sütü yok, sadece su ısıtıcısı var.'::text),
(301905,33545,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld! Állítólag nincs ... teje, csak a vízforraló.'::text,'sok'::text,'sok'::text,'némi'::text,'Képzeld! Állítólag nincs sok teje, csak a vízforraló.'::text),
(301908,33546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, da ... fünf Becher, die auf den Wasserkocher warten, echt jetzt.'::text,'sind'::text,'ist'::text,'sein'::text,'Ey, da sind fünf Becher, die auf den Wasserkocher warten, echt jetzt.'::text),
(301912,33546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, тут ... п''ять кухлів, які чекають на чайник, чесно.'::text,'є'::text,'є'::text,'бути'::text,'Йо, тут є п''ять кухлів, які чекають на чайник, чесно.'::text),
(301911,33546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... cinco tazas esperando al hervidor, en serio.'::text,'hay'::text,'hay'::text,'hay'::text,'Tío, hay cinco tazas esperando al hervidor, en serio.'::text),
(301910,33546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... cinq mugs qui attendent la bouilloire, sans mentir.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Wesh, il y a cinq mugs qui attendent la bouilloire, sans mentir.'::text),
(301913,33546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, su ısıtıcısını bekleyen beş kupa ..., cidden.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, su ısıtıcısını bekleyen beş kupa var, cidden.'::text),
(301914,33546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, öt bögre ... a vízforralóra várva, komolyan.'::text,'van'::text,'van'::text,'lenni'::text,'Figyu, öt bögre van a vízforralóra várva, komolyan.'::text),
(304131,33793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move: Du ... den richtigen Schlüssel für das Schloss.'::text,'hast'::text,'hat'::text,'hast'::text,'Starker Move: Du hast den richtigen Schlüssel für das Schloss.'::text),
(304135,33793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спритно: ти ... правильний ключ від того замка.'::text,'маєш'::text,'має'::text,'маєш'::text,'Спритно: ти маєш правильний ключ від того замка.'::text),
(304134,33793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buena jugada: ... la llave correcta para esa cerradura.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Buena jugada: tienes la llave correcta para esa cerradura.'::text),
(304133,33793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien joué : tu ... la bonne clé pour cette serrure.'::text,'as'::text,'a'::text,'as'::text,'Bien joué : tu as la bonne clé pour cette serrure.'::text),
(304136,33793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şık hamle: sende o kilidin doğru anahtarı ...'::text,'var'::text,'var'::text,'var'::text,'Şık hamle: sende o kilidin doğru anahtarı var.'::text),
(304137,33793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás: neked ... a jó kulcsod ahhoz a zárhoz.'::text,'van'::text,'van'::text,'van'::text,'Ügyes húzás: neked van a jó kulcsod ahhoz a zárhoz.'::text),
(304149,33795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit dem Schlüssel ... sie das Schloss öffnen.'::text,'kann'::text,'kann'::text,'kann'::text,'Mit dem Schlüssel kann sie das Schloss öffnen.'::text),
(304153,33795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ключем вона ... відімкнути замок.'::text,'може'::text,'може'::text,'може'::text,'Ключем вона може відімкнути замок.'::text),
(304152,33795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con la llave, ... abrir la cerradura.'::text,'puede'::text,'puede'::text,'puede'::text,'Con la llave, puede abrir la cerradura.'::text),
(304151,33795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec la clé, elle ... ouvrir la serrure.'::text,'peut'::text,'peut'::text,'peut'::text,'Avec la clé, elle peut ouvrir la serrure.'::text),
(304154,33795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anahtarla kilidi ...'::text,'açabilir'::text,'açabilir'::text,'açabilir'::text,'Anahtarla kilidi açabilir.'::text),
(304155,33795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kulccsal ki ... nyitni a zárat.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'A kulccsal ki tudja nyitni a zárat.'::text),
(304158,33796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat viele ..., aber nur einer passt ins Schloss.'::text,'Schlüssel'::text,'Schlüssel'::text,'Schlüssel'::text,'Sie hat viele Schlüssel, aber nur einer passt ins Schloss.'::text),
(304162,33796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї багато ..., але до замка підходить лише один.'::text,'ключів'::text,'ключ'::text,'ключів'::text,'У неї багато ключів, але до замка підходить лише один.'::text),
(304161,33796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene muchas ..., pero solo una encaja en la cerradura.'::text,'llaves'::text,'llave'::text,'llaves'::text,'Tiene muchas llaves, pero solo una encaja en la cerradura.'::text),
(304160,33796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a beaucoup de ..., mais une seule va dans la serrure.'::text,'clés'::text,'clé'::text,'clés'::text,'Elle a beaucoup de clés, mais une seule va dans la serrure.'::text),
(304163,33796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elinde bir sürü ... var ama kilide sadece biri uyuyor.'::text,'anahtar'::text,'anahtar'::text,'anahtar'::text,'Elinde bir sürü anahtar var ama kilide sadece biri uyuyor.'::text),
(304164,33796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sok ... van, de csak egy illik a zárba.'::text,'kulcsa'::text,'kulcsa'::text,'kulcsa'::text,'Sok kulcsa van, de csak egy illik a zárba.'::text),
(304167,33797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Tür hat ein Schloss. Sie macht gleich ... Schloss auf.'::text,'das'::text,'ein'::text,'ein'::text,'Alter, die Tür hat ein Schloss. Sie macht gleich das Schloss auf.'::text),
(304171,33797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у дверях є замок. Вона зараз відімкне ... замок.'::text,''::text,NULL::text,NULL::text,'Бро, у дверях є замок. Вона зараз відімкне замок.'::text),
(304170,33797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la puerta tiene cerradura. Va a abrir ... cerradura.'::text,'la'::text,'una'::text,'una'::text,'Tío, la puerta tiene cerradura. Va a abrir la cerradura.'::text),
(304169,33797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la porte a une serrure. Elle va ouvrir ... serrure.'::text,'la'::text,'une'::text,'une'::text,'Frère, la porte a une serrure. Elle va ouvrir la serrure.'::text),
(304172,33797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kapının kilidi var. Şimdi ... kilidi açacak.'::text,''::text,'bir'::text,'bir'::text,'Kanka, kapının kilidi var. Şimdi kilidi açacak.'::text),
(304173,33797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az ajtón van egy zár. Mindjárt kinyitja ... zárat.'::text,'a'::text,'egy'::text,'egy'::text,'Tesó, az ajtón van egy zár. Mindjárt kinyitja a zárat.'::text),
(304176,33798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ... Schlüssel müssen das Schloss da aufmachen.'::text,'diese'::text,'dieser'::text,'jener'::text,'Ey, diese Schlüssel müssen das Schloss da aufmachen.'::text),
(304180,33798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... ключі мають відімкнути той замок.'::text,'ці'::text,'цей'::text,'той'::text,'Йо, ці ключі мають відімкнути той замок.'::text),
(304179,33798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... llaves tienen que abrir esa cerradura.'::text,'estas'::text,'esta'::text,'esa'::text,'Tío, estas llaves tienen que abrir esa cerradura.'::text),
(304178,33798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... clés doivent ouvrir cette serrure.'::text,'ces'::text,'cette'::text,'cette'::text,'Wesh, ces clés doivent ouvrir cette serrure.'::text),
(304181,33798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... anahtarlar o kilidi açmalı.'::text,'bu'::text,'bu'::text,'şu'::text,'Kanka, bu anahtarlar o kilidi açmalı.'::text),
(304182,33798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... a kulcsoknak kell kinyitniuk azt a zárat.'::text,'ezeknek'::text,'ennek'::text,'annak'::text,'Figyu, ezeknek a kulcsoknak kell kinyitniuk azt a zárat.'::text),
(304185,33799,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: 50 Euro. Sie ... ein besseres Schloss für diese Tür kaufen.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Budget: 50 Euro. Sie sollte ein besseres Schloss für diese Tür kaufen.'::text),
(304189,33799,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: 50 євро. Вона ... купити кращий замок для цих дверей.'::text,'мала б'::text,'мала б'::text,'буде'::text,'Бюджет: 50 євро. Вона мала б купити кращий замок для цих дверей.'::text),
(304188,33799,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: 50 euros. ... comprar una cerradura mejor para esta puerta.'::text,'Debería'::text,'Debería'::text,'Deberá'::text,'Presupuesto: 50 euros. Debería comprar una cerradura mejor para esta puerta.'::text),
(304187,33799,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : 50 euros. Elle ... acheter une meilleure serrure pour cette porte.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Budget : 50 euros. Elle devrait acheter une meilleure serrure pour cette porte.'::text),
(304190,33799,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: 50 avro. Bu kapı için daha iyi bir kilit ...'::text,'almalı'::text,'almalı'::text,'alacak'::text,'Bütçe: 50 avro. Bu kapı için daha iyi bir kilit almalı.'::text),
(304191,33799,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: 50 euró. Jobb zárat ... vennie ehhez az ajtóhoz.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Költségvetés: 50 euró. Jobb zárat kellene vennie ehhez az ajtóhoz.'::text),
(302133,33571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: 1 Krone. Der König sitzt auf ... goldenen Thron.'::text,'seinem'::text,'ihrem'::text,'seinem'::text,'Budget: 1 Krone. Der König sitzt auf seinem goldenen Thron.'::text),
(302137,33571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: 1 корона. Король сидить на ... золотому троні.'::text,'своєму'::text,'своєму'::text,'своєму'::text,'Бюджет: 1 корона. Король сидить на своєму золотому троні.'::text),
(302136,33571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: 1 corona. El rey se sienta en ... trono dorado.'::text,'su'::text,'su'::text,'su'::text,'Presupuesto: 1 corona. El rey se sienta en su trono dorado.'::text),
(302135,33571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : 1 couronne. Le roi est assis sur ... trône doré.'::text,'son'::text,'son'::text,'son'::text,'Budget : 1 couronne. Le roi est assis sur son trône doré.'::text),
(302138,33571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: 1 taç. Kral ... altın tahtına oturuyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Bütçe: 1 taç. Kral onun altın tahtına oturuyor.'::text),
(302139,33571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: 1 korona. A király az arany ... ül.'::text,'trónján'::text,'trónján'::text,'trónján'::text,'Költségvetés: 1 korona. A király az arany trónján ül.'::text),
(302151,33573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der König steht ... dem Balkon! Die Menge kreischt!'::text,'auf'::text,'in'::text,'unter'::text,'Der König steht auf dem Balkon! Die Menge kreischt!'::text),
(302155,33573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Король стоїть ... балконі! Натовп кричить!'::text,'на'::text,'в'::text,'під'::text,'Король стоїть на балконі! Натовп кричить!'::text),
(302154,33573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El rey está de pie ... el balcón! ¡La multitud grita!'::text,'en'::text,'en'::text,'debajo de'::text,'¡El rey está de pie en el balcón! ¡La multitud grita!'::text),
(302153,33573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le roi se tient ... le balcon ! La foule hurle !'::text,'sur'::text,'dans'::text,'sous'::text,'Le roi se tient sur le balcon ! La foule hurle !'::text),
(302156,33573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kral balkonun ... duruyor! Kalabalık çığlık atıyor!'::text,'üstünde'::text,'içinde'::text,'altında'::text,'Kral balkonun üstünde duruyor! Kalabalık çığlık atıyor!'::text),
(302157,33573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A király ... áll! Ordít a tömeg!'::text,'az erkélyen'::text,'az erkélyben'::text,'az erkély alatt'::text,'A király az erkélyen áll! Ordít a tömeg!'::text),
(302160,33574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der König hat ... Krone! Nur eine! Niemand klaut sie!'::text,'eine'::text,'die erste'::text,'einmal'::text,'Der König hat eine Krone! Nur eine! Niemand klaut sie!'::text),
(302164,33574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У короля ... корона! Лише одна! Ніхто її не вкраде!'::text,'одна'::text,'перша'::text,'один раз'::text,'У короля одна корона! Лише одна! Ніхто її не вкраде!'::text),
(302163,33574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El rey tiene ... corona! ¡Solo una! ¡Nadie se la roba!'::text,'una'::text,'la primera'::text,'una vez'::text,'¡El rey tiene una corona! ¡Solo una! ¡Nadie se la roba!'::text),
(302162,33574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le roi a ... couronne ! Une seule ! Personne ne la vole !'::text,'une'::text,'la première'::text,'une fois'::text,'Le roi a une couronne ! Une seule ! Personne ne la vole !'::text),
(302165,33574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kralın ... tacı var! Sadece bir tane! Kimse onu çalamaz!'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Kralın bir tacı var! Sadece bir tane! Kimse onu çalamaz!'::text),
(302166,33574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A királynak ... koronája van! Csak egy! Senki nem lopja el!'::text,'egy'::text,'első'::text,'egyszer'::text,'A királynak egy koronája van! Csak egy! Senki nem lopja el!'::text),
(302178,33576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, der König versteckt sich normalerweise, aber gestern ... er der Menge zu, anscheinend.'::text,'winkte'::text,'winkt'::text,NULL::text,'Hör zu, der König versteckt sich normalerweise, aber gestern winkte er der Menge zu, anscheinend.'::text),
(302182,33576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, король зазвичай ховається, але вчора, кажуть, ... натовпу.'::text,'помахав'::text,'махає'::text,NULL::text,'Слухай, король зазвичай ховається, але вчора, кажуть, помахав натовпу.'::text),
(302181,33576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, el rey normalmente se esconde, pero ayer ... a la multitud, al parecer.'::text,'saludó'::text,'saluda'::text,NULL::text,'Escucha, el rey normalmente se esconde, pero ayer saludó a la multitud, al parecer.'::text),
(302180,33576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, le roi se cache d''habitude, mais hier il ... à la foule, apparemment.'::text,'a fait signe'::text,'fait signe'::text,NULL::text,'Écoute, le roi se cache d''habitude, mais hier il a fait signe à la foule, apparemment.'::text),
(302183,33576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, kral genelde saklanır ama dün kalabalığa el ..., öyle diyorlar.'::text,'salladı'::text,'sallar'::text,NULL::text,'Dinle, kral genelde saklanır ama dün kalabalığa el salladı, öyle diyorlar.'::text),
(302184,33576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a király általában bujkál, de tegnap állítólag ... a tömegnek.'::text,'integetett'::text,'integet'::text,NULL::text,'Figyelj, a király általában bujkál, de tegnap állítólag integetett a tömegnek.'::text),
(302187,33577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der König ... jetzt auf dem goldenen Thron.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Der König sitzt jetzt auf dem goldenen Thron.'::text),
(302191,33577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Король зараз ... на золотому троні.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Король зараз сидить на золотому троні.'::text),
(302190,33577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El rey ... ahora en el trono dorado.'::text,'está sentado'::text,'se sienta'::text,'está sentado'::text,'El rey está sentado ahora en el trono dorado.'::text),
(302189,33577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le roi ... sur le trône doré maintenant.'::text,'est assis'::text,'s''assoit'::text,'est assis'::text,'Le roi est assis sur le trône doré maintenant.'::text),
(302192,33577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kral şimdi altın tahtta ...'::text,'oturuyor'::text,'oturur'::text,'oturuyor'::text,'Kral şimdi altın tahtta oturuyor.'::text),
(302193,33577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A király most az arany trónon ...'::text,'ül'::text,'ül'::text,'ül'::text,'A király most az arany trónon ül.'::text),
(302196,33578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der König bleibt normalerweise drinnen, aber jetzt ... er auf dem Balkon.'::text,'steht'::text,'steht'::text,NULL::text,'Der König bleibt normalerweise drinnen, aber jetzt steht er auf dem Balkon.'::text),
(302200,33578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Король зазвичай сидить усередині, але зараз ... на балконі.'::text,'стоїть'::text,'стоїть'::text,NULL::text,'Король зазвичай сидить усередині, але зараз стоїть на балконі.'::text),
(302199,33578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El rey normalmente se queda dentro, pero ahora ... en el balcón.'::text,'está de pie'::text,'está de pie'::text,NULL::text,'El rey normalmente se queda dentro, pero ahora está de pie en el balcón.'::text),
(302198,33578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le roi reste d''habitude à l''intérieur, mais maintenant il ... sur le balcon.'::text,'est debout'::text,'est debout'::text,NULL::text,'Le roi reste d''habitude à l''intérieur, mais maintenant il est debout sur le balcon.'::text),
(302201,33578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kral genelde içeride kalır ama şimdi balkonda ...'::text,'duruyor'::text,'durur'::text,NULL::text,'Kral genelde içeride kalır ama şimdi balkonda duruyor.'::text),
(302202,33578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A király általában bent marad, de most az erkélyen ...'::text,'áll'::text,'áll'::text,NULL::text,'A király általában bent marad, de most az erkélyen áll.'::text),
(307173,34131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, ich ... dich für immer lieben, auch wenn wir alt sind!'::text,'werde'::text,'werde'::text,'liebend'::text,'Ich verspreche, ich werde dich für immer lieben, auch wenn wir alt sind!'::text),
(307177,34131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, я ... тебе завжди, навіть коли ми будемо старими!'::text,'кохатиму'::text,'кохатиму'::text,'кохаючи'::text,'Обіцяю, я кохатиму тебе завжди, навіть коли ми будемо старими!'::text),
(307176,34131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Te lo prometo, te ... para siempre, incluso cuando seamos viejos!'::text,'querré'::text,'querré'::text,'queriendo'::text,'¡Te lo prometo, te querré para siempre, incluso cuando seamos viejos!'::text),
(307175,34131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je te promets, je ... pour toujours, même quand on sera vieux !'::text,'t''aimerai'::text,'t''aimerai'::text,'t''aimant'::text,'Je te promets, je t''aimerai pour toujours, même quand on sera vieux !'::text),
(307178,34131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, seni sonsuza dek ..., yaşlandığımızda bile!'::text,'seveceğim'::text,'seveceğim'::text,'severek'::text,'Söz veriyorum, seni sonsuza dek seveceğim, yaşlandığımızda bile!'::text),
(307179,34131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, örökké ... téged, még ha öregek leszünk is!'::text,'szeretni foglak'::text,'szeretni foglak'::text,'szeretve'::text,'Megígérem, örökké szeretni foglak téged, még ha öregek leszünk is!'::text),
(307182,34132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau sie dir an! Wir ... alt und für immer verliebt sein!'::text,'werden'::text,'wird'::text,'werden'::text,'Schau sie dir an! Wir werden alt und für immer verliebt sein!'::text),
(307186,34132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подивись на них! Ми ... старими й закоханими назавжди!'::text,'збираємося бути'::text,'збирається бути'::text,'збираємося бути'::text,'Подивись на них! Ми збираємося бути старими й закоханими назавжди!'::text),
(307185,34132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Míralos! ¡... viejos y enamorados para siempre!'::text,'Vamos a ser'::text,'Va a ser'::text,'Vamos a ser'::text,'¡Míralos! ¡Vamos a ser viejos y enamorados para siempre!'::text),
(307184,34132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde-les ! Nous ... vieux et amoureux pour toujours !'::text,'allons être'::text,'va être'::text,'allons être'::text,'Regarde-les ! Nous allons être vieux et amoureux pour toujours !'::text),
(307187,34132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlara bak! Biz de yaşlı ve sonsuza dek aşık ...!'::text,'olacağız'::text,'olacak'::text,'olacağız'::text,'Onlara bak! Biz de yaşlı ve sonsuza dek aşık olacağız!'::text),
(307188,34132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd őket! Mi is öregek és örökké szerelmesek ...!'::text,'leszünk'::text,'lesz'::text,'leszünk'::text,'Nézd őket! Mi is öregek és örökké szerelmesek leszünk!'::text),
(307191,34133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, das alte Paar hat einen Termin gebucht. Sie ... wieder heiraten.'::text,'werden'::text,'werden'::text,NULL::text,'Also, ich hab gehört, das alte Paar hat einen Termin gebucht. Sie werden wieder heiraten.'::text),
(307195,34133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, я чула, що старенька пара забронювала дату. Вони ... знову.'::text,'збираються одружитися'::text,'одружаться'::text,NULL::text,'Короче, я чула, що старенька пара забронювала дату. Вони збираються одружитися знову.'::text),
(307194,34133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que la pareja de ancianos ha reservado fecha. ... otra vez.'::text,'Van a casarse'::text,'Se casarán'::text,NULL::text,'Vale, me han dicho que la pareja de ancianos ha reservado fecha. Van a casarse otra vez.'::text),
(307193,34133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu que le vieux couple a réservé une date. Ils ... de nouveau.'::text,'vont se marier'::text,'se marieront'::text,NULL::text,'Bon, j''ai entendu que le vieux couple a réservé une date. Ils vont se marier de nouveau.'::text),
(307196,34133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki yaşlı çift bir tarih ayırtmış. Yeniden ...'::text,'evlenecekler'::text,'evlenecekler'::text,NULL::text,'Tamam, duydum ki yaşlı çift bir tarih ayırtmış. Yeniden evlenecekler.'::text),
(307197,34133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt hallottam, hogy az idős pár lefoglalt egy időpontot. Újra ... házasodni.'::text,'össze fognak'::text,'össze fognak'::text,NULL::text,'Szóval, azt hallottam, hogy az idős pár lefoglalt egy időpontot. Újra össze fognak házasodni.'::text),
(307200,34134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass seine Frau ... ist als er.'::text,'älter'::text,'älter'::text,'am ältesten'::text,'Mädel, er hat mir erzählt, dass seine Frau älter ist als er.'::text),
(307204,34134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що його дружина ... за нього.'::text,'старша'::text,'більш стара'::text,'найстарша'::text,'Подруго, він сказав мені, що його дружина старша за нього.'::text),
(307203,34134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que su mujer es ... que él.'::text,'mayor'::text,'mayor'::text,'la mayor'::text,'Tía, me dijo que su mujer es mayor que él.'::text),
(307202,34134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit que sa femme est ... que lui.'::text,'plus âgée'::text,'plus âgée'::text,'la plus âgée'::text,'Ma belle, il m''a dit que sa femme est plus âgée que lui.'::text),
(307205,34134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana karısının kendisinden ... olduğunu söyledi.'::text,'daha yaşlı'::text,'daha yaşlı'::text,'en yaşlı'::text,'Kızım, bana karısının kendisinden daha yaşlı olduğunu söyledi.'::text),
(307206,34134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a felesége ... nála.'::text,'idősebb'::text,'idősebb'::text,'legidősebb'::text,'Csajszi, azt mondta, hogy a felesége idősebb nála.'::text),
(307209,34135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Arzt sagt, der alte Mann ... jeden Tag spazieren gehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Der Arzt sagt, der alte Mann muss jeden Tag spazieren gehen.'::text),
(307213,34135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікар каже, що старий чоловік ... гуляти щодня.'::text,'має'::text,'мусить'::text,'мав би'::text,'Лікар каже, що старий чоловік має гуляти щодня.'::text),
(307212,34135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El médico dice que el anciano ... caminar todos los días.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El médico dice que el anciano tiene que caminar todos los días.'::text),
(307211,34135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le médecin dit que le vieil homme ... marcher tous les jours.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le médecin dit que le vieil homme doit marcher tous les jours.'::text),
(307214,34135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktor diyor ki yaşlı adam her gün ...'::text,'yürümek zorunda'::text,'yürümeli'::text,'yürümeli'::text,'Doktor diyor ki yaşlı adam her gün yürümek zorunda.'::text),
(307215,34135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos szerint az idős férfinak minden nap ... sétálnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Az orvos szerint az idős férfinak minden nap kell sétálnia.'::text),
(307227,34137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann küsst sie ..., weil er sanft ist.'::text,'sanft'::text,'sanft'::text,'Sanftheit'::text,'Der alte Mann küsst sie sanft, weil er sanft ist.'::text),
(307231,34137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий чоловік цілує її ..., бо він ніжний.'::text,'ніжно'::text,'ніжний'::text,'ніжність'::text,'Старий чоловік цілує її ніжно, бо він ніжний.'::text),
(307230,34137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano la besa ... porque es tierno.'::text,'tiernamente'::text,'tierno'::text,'ternura'::text,'El anciano la besa tiernamente porque es tierno.'::text),
(307229,34137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme l''embrasse ... parce qu''il est doux.'::text,'doucement'::text,'doux'::text,'douceur'::text,'Le vieil homme l''embrasse doucement parce qu''il est doux.'::text),
(307232,34137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam onu ... öpüyor çünkü o nazik.'::text,'nazikçe'::text,'nazik'::text,'naziklik'::text,'Yaşlı adam onu nazikçe öpüyor çünkü o nazik.'::text),
(307233,34137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős férfi ... megcsókolja, mert gyengéd.'::text,'gyengéden'::text,'gyengéd'::text,'gyengédség'::text,'Az idős férfi gyengéden megcsókolja, mert gyengéd.'::text),
(313554,34840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris ... so viel Romantik, es ist echt zu viel!'::text,'hat'::text,'haben'::text,'hat'::text,'Paris hat so viel Romantik, es ist echt zu viel!'::text),
(313558,34840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Париж ... стільки романтики, це вже занадто!'::text,'має'::text,'мати'::text,'має'::text,'Париж має стільки романтики, це вже занадто!'::text),
(313557,34840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡París ... tanto romanticismo que es absolutamente demasiado!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡París tiene tanto romanticismo que es absolutamente demasiado!'::text),
(313556,34840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris ... tellement de romantisme, c''est carrément trop !'::text,'a'::text,'ont'::text,'a'::text,'Paris a tellement de romantisme, c''est carrément trop !'::text),
(313559,34840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris''in o kadar çok romantizmi ... ki bu resmen fazla!'::text,'var'::text,'var'::text,'var'::text,'Paris''in o kadar çok romantizmi var ki bu resmen fazla!'::text),
(313560,34840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Párizsnak annyi romantikája ..., hogy az már abszolút túl sok!'::text,'van'::text,'van'::text,'van'::text,'Párizsnak annyi romantikája van, hogy az már abszolút túl sok!'::text),
(313572,34842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Romantik ... in Paris in jedem Alter passieren.'::text,'kann'::text,'kann'::text,'ist'::text,'Romantik kann in Paris in jedem Alter passieren.'::text),
(313576,34842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Роман у Парижі ... статися в будь-якому віці.'::text,'може'::text,'може'::text,'є'::text,'Роман у Парижі може статися в будь-якому віці.'::text),
(313575,34842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El romance ... surgir a cualquier edad en París.'::text,'puede'::text,'puede'::text,'está'::text,'El romance puede surgir a cualquier edad en París.'::text),
(313574,34842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La romance ... arriver à tout âge à Paris.'::text,'peut'::text,'peut'::text,'est'::text,'La romance peut arriver à tout âge à Paris.'::text),
(313577,34842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris''te romantizm her yaşta ...'::text,'yaşanabilir'::text,'yaşanabilir'::text,NULL::text,'Paris''te romantizm her yaşta yaşanabilir.'::text),
(313578,34842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Párizsban a romantika bármilyen korban ...'::text,'megtörténhet'::text,'megtörténhet'::text,'van'::text,'Párizsban a romantika bármilyen korban megtörténhet.'::text),
(313581,34843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Romanze endet mit einer langen Umarmung ... dem Gehweg.'::text,'auf'::text,'in'::text,'an'::text,'Die Romanze endet mit einer langen Umarmung auf dem Gehweg.'::text),
(313585,34843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Роман закінчується довгими обіймами ... тротуарі.'::text,'на'::text,'в'::text,'біля'::text,'Роман закінчується довгими обіймами на тротуарі.'::text),
(313584,34843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El romance termina con un largo abrazo ... la acera.'::text,'en'::text,'en'::text,'a'::text,'El romance termina con un largo abrazo en la acera.'::text),
(313583,34843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La romance se termine par un long câlin ... le trottoir.'::text,'sur'::text,'dans'::text,'à'::text,'La romance se termine par un long câlin sur le trottoir.'::text),
(313586,34843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Romantizm kaldırımın ... uzun bir sarılmayla bitiyor.'::text,'üstünde'::text,'içinde'::text,NULL::text,'Romantizm kaldırımın üstünde uzun bir sarılmayla bitiyor.'::text),
(313587,34843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A románc a ... egy hosszú öleléssel ér véget.'::text,'járdán'::text,'járdában'::text,'járdánál'::text,'A románc a járdán egy hosszú öleléssel ér véget.'::text),
(313590,34844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Video zeigt ... Paare und jede Menge Romantik.'::text,'drei'::text,'dritte'::text,'Dreien'::text,'Das Video zeigt drei Paare und jede Menge Romantik.'::text),
(313594,34844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відео показує ... пари й багато романтики.'::text,'три'::text,'треті'::text,'трійки'::text,'Відео показує три пари й багато романтики.'::text),
(313593,34844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vídeo muestra ... parejas y mucho romanticismo.'::text,'tres'::text,'terceras'::text,'tres'::text,'El vídeo muestra tres parejas y mucho romanticismo.'::text),
(313592,34844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vidéo montre ... couples et beaucoup de romantisme.'::text,'trois'::text,'troisièmes'::text,'trois'::text,'La vidéo montre trois couples et beaucoup de romantisme.'::text),
(313595,34844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Video ... çift ve bolca romantizm gösteriyor.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Video üç çift ve bolca romantizm gösteriyor.'::text),
(313596,34844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A videó ... párt és rengeteg romantikát mutat.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'A videó három párt és rengeteg romantikát mutat.'::text),
(313599,34845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In Paris kostet Romantik kein ..., nur zwei Cappuccinos.'::text,'Geld'::text,'Geld'::text,'ein Geld'::text,'In Paris kostet Romantik kein Geld, nur zwei Cappuccinos.'::text),
(313603,34845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У Парижі романтика не коштує ..., лише два капучино.'::text,'грошей'::text,'грошей'::text,'грошей'::text,'У Парижі романтика не коштує грошей, лише два капучино.'::text),
(313602,34845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En París, el romance no cuesta ..., solo dos capuchinos.'::text,'dinero'::text,'dinero'::text,'un dinero'::text,'En París, el romance no cuesta dinero, solo dos capuchinos.'::text),
(313601,34845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À Paris, la romance ne coûte pas ..., juste deux cappuccinos.'::text,'d''argent'::text,'d''argent'::text,'un argent'::text,'À Paris, la romance ne coûte pas d''argent, juste deux cappuccinos.'::text),
(313604,34845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris''te romantizm hiç ... tutmuyor, sadece iki kapuçino.'::text,'para'::text,'para'::text,'bir para'::text,'Paris''te romantizm hiç para tutmuyor, sadece iki kapuçino.'::text),
(313605,34845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Párizsban a romantika nem kerül ..., csak két cappuccinóba.'::text,'pénzbe'::text,'pénzbe'::text,'egy pénzbe'::text,'Párizsban a romantika nem kerül pénzbe, csak két cappuccinóba.'::text),
(313617,34847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In Paris ... Romantik überall, wirklich überall!'::text,'ist'::text,'sind'::text,'sein'::text,'In Paris ist Romantik überall, wirklich überall!'::text),
(313621,34847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У Парижі ... романтика всюди, абсолютно всюди!'::text,'є'::text,'є'::text,'бути'::text,'У Парижі є романтика всюди, абсолютно всюди!'::text),
(313620,34847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En París ... romanticismo por todas partes, absolutamente por todas partes!'::text,'hay'::text,'hay'::text,'hay'::text,'¡En París hay romanticismo por todas partes, absolutamente por todas partes!'::text),
(313619,34847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À Paris, ... de la romance partout, absolument partout !'::text,'il y a'::text,'il y a'::text,'il y a'::text,'À Paris, il y a de la romance partout, absolument partout !'::text),
(313622,34847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Paris''te her yerde romantizm ..., kesinlikle her yerde!'::text,'var'::text,'var'::text,'olmak'::text,'Paris''te her yerde romantizm var, kesinlikle her yerde!'::text),
(313623,34847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Párizsban mindenhol ... romantika, abszolút mindenhol!'::text,'van'::text,'vannak'::text,'lenni'::text,'Párizsban mindenhol van romantika, abszolút mindenhol!'::text),
(313068,34786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... reich und kochst trotzdem selbst. Respekt.'::text,'bist'::text,'ist'::text,'bin'::text,'Du bist reich und kochst trotzdem selbst. Respekt.'::text),
(313072,34786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... багатий, і все одно готуєш сам. Респект.'::text,'є'::text,'є'::text,'є'::text,'Ти є багатий, і все одно готуєш сам. Респект.'::text),
(313071,34786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rico y aun así cocinas tú mismo. Mis respetos.'::text,'Eres'::text,'Es'::text,'Soy'::text,'Eres rico y aun así cocinas tú mismo. Mis respetos.'::text),
(313070,34786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... riche, et tu cuisines quand même toi-même. Respect.'::text,'es'::text,'est'::text,'suis'::text,'Tu es riche, et tu cuisines quand même toi-même. Respect.'::text),
(313073,34786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zengin ... ve yine de kendi yemeğini yapıyorsun. Helal olsun.'::text,''::text,NULL::text,NULL::text,'Zengin ve yine de kendi yemeğini yapıyorsun. Helal olsun.'::text),
(313074,34786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gazdag ..., és mégis magadnak főzöl. Respekt.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Gazdag vagy, és mégis magadnak főzöl. Respekt.'::text),
(313086,34788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der reiche Mann ... Paprika in einer Pfanne am Fenster.'::text,'schwenkte'::text,'schwenkt'::text,'schwenken'::text,'Der reiche Mann schwenkte Paprika in einer Pfanne am Fenster.'::text),
(313090,34788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Багатий чоловік ... перці на сковороді біля вікна.'::text,'підкидав'::text,'підкидає'::text,'підкидати'::text,'Багатий чоловік підкидав перці на сковороді біля вікна.'::text),
(313089,34788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre rico ... pimientos en una sartén junto a la ventana.'::text,'salteó'::text,'saltea'::text,'saltear'::text,'El hombre rico salteó pimientos en una sartén junto a la ventana.'::text),
(313088,34788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme riche ... des poivrons dans une poêle près de la fenêtre.'::text,'a fait sauter'::text,'fait sauter'::text,'faire sauter'::text,'L''homme riche a fait sauter des poivrons dans une poêle près de la fenêtre.'::text),
(313091,34788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zengin adam pencerenin yanında tavada biberleri ...'::text,'soteledi'::text,'soteler'::text,'sotelemek'::text,'Zengin adam pencerenin yanında tavada biberleri soteledi.'::text),
(313092,34788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazdag férfi ... a paprikát egy serpenyőben az ablaknál.'::text,'dobálta'::text,'dobálja'::text,'dobálni'::text,'A gazdag férfi dobálta a paprikát egy serpenyőben az ablaknál.'::text),
(313095,34789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist reich und kocht zu Hause, aber gestern ... er auswärts.'::text,'aß'::text,'isst'::text,NULL::text,'Er ist reich und kocht zu Hause, aber gestern aß er auswärts.'::text),
(313099,34789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він багатий і готує вдома, але вчора ... не вдома.'::text,'їв'::text,'їсть'::text,NULL::text,'Він багатий і готує вдома, але вчора їв не вдома.'::text),
(313098,34789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es rico y cocina en casa, pero ayer ... fuera.'::text,'comió'::text,'come'::text,NULL::text,'Es rico y cocina en casa, pero ayer comió fuera.'::text),
(313097,34789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est riche et cuisine chez lui, mais hier il ... dehors.'::text,'a mangé'::text,'mange'::text,NULL::text,'Il est riche et cuisine chez lui, mais hier il a mangé dehors.'::text),
(313100,34789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zengin ve evde yemek yapar ama dün dışarıda ...'::text,'yedi'::text,'yer'::text,NULL::text,'Zengin ve evde yemek yapar ama dün dışarıda yedi.'::text),
(313101,34789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gazdag, és otthon főz, de tegnap házon kívül ...'::text,'evett'::text,'eszik'::text,NULL::text,'Gazdag, és otthon főz, de tegnap házon kívül evett.'::text),
(313104,34790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buchstäblich ein König! Der reiche Mann ... die Arme weit über der Pfanne aus!'::text,'breitet'::text,'breitet'::text,'breitet'::text,'Buchstäblich ein König! Der reiche Mann breitet die Arme weit über der Pfanne aus!'::text),
(313108,34790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Буквально король! Багатий чоловік широко ... руки над сковородою!'::text,'розводить'::text,'розводить'::text,'розводить'::text,'Буквально король! Багатий чоловік широко розводить руки над сковородою!'::text),
(313107,34790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Literalmente un rey! ¡El hombre rico ... los brazos de par en par sobre la sartén!'::text,'está abriendo'::text,'abre'::text,'está abriendo'::text,'¡Literalmente un rey! ¡El hombre rico está abriendo los brazos de par en par sobre la sartén!'::text),
(313106,34790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Littéralement un roi ! L''homme riche ... grand les bras au-dessus de la poêle !'::text,'est en train d''ouvrir'::text,'ouvre'::text,'est en train d''ouvrir'::text,'Littéralement un roi ! L''homme riche est en train d''ouvrir grand les bras au-dessus de la poêle !'::text),
(313109,34790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resmen kral! Zengin adam kollarını tavanın üstünde iki yana ...!'::text,'açıyor'::text,'açar'::text,'açıyor'::text,'Resmen kral! Zengin adam kollarını tavanın üstünde iki yana açıyor!'::text),
(313110,34790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szó szerint egy király! A gazdag férfi szélesre ... a karját a serpenyő fölött!'::text,'tárja'::text,'tárja'::text,'tárja'::text,'Szó szerint egy király! A gazdag férfi szélesre tárja a karját a serpenyő fölött!'::text),
(313122,34792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, dass er ... ist als alle in der Stadt.'::text,'reicher'::text,'reicher'::text,'am reichsten'::text,'Bestie, sie hat mir erzählt, dass er reicher ist als alle in der Stadt.'::text),
(313126,34792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що він ... за всіх у місті.'::text,'багатший'::text,'більш багатий'::text,'найбагатший'::text,'Подруго, вона сказала мені, що він багатший за всіх у місті.'::text),
(313125,34792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que él es ... que todo el mundo en la ciudad.'::text,'más rico'::text,'más rico'::text,'el más rico'::text,'Tía, me dijo que él es más rico que todo el mundo en la ciudad.'::text),
(313124,34792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''il est ... que tout le monde en ville.'::text,'plus riche'::text,'plus riche'::text,'le plus riche'::text,'Ma belle, elle m''a dit qu''il est plus riche que tout le monde en ville.'::text),
(313127,34792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana onun şehirdeki herkesten ... olduğunu söyledi.'::text,'daha zengin'::text,'daha zengin'::text,'en zengin'::text,'Kanka, bana onun şehirdeki herkesten daha zengin olduğunu söyledi.'::text),
(313128,34792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ő ... mindenkinél a városban.'::text,'gazdagabb'::text,'gazdagabb'::text,'leggazdagabb'::text,'Csajszi, azt mondta, hogy ő gazdagabb mindenkinél a városban.'::text),
(313131,34793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, der reiche Typ kocht auch richtig ...'::text,'gut'::text,'gut'::text,'gut'::text,'Hör zu, ich hab gehört, der reiche Typ kocht auch richtig gut.'::text),
(313135,34793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що той багатий хлопець ще й готує дуже ...'::text,'добре'::text,'добрий'::text,'добре'::text,'Слухай, я чула, що той багатий хлопець ще й готує дуже добре.'::text),
(313134,34793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me han dicho que el ricachón además cocina muy ...'::text,'bien'::text,'bueno'::text,'bien'::text,'Escucha, me han dicho que el ricachón además cocina muy bien.'::text),
(313133,34793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que le mec riche cuisine aussi très ...'::text,'bien'::text,'bon'::text,'bien'::text,'Écoute, j''ai entendu que le mec riche cuisine aussi très bien.'::text),
(313136,34793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki o zengin adam çok da ... yemek yapıyormuş.'::text,'iyi'::text,'iyi'::text,'iyi'::text,'Dinle, duydum ki o zengin adam çok da iyi yemek yapıyormuş.'::text),
(313137,34793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a gazdag srác ráadásul nagyon ... főz.'::text,'jól'::text,'jó'::text,'jól'::text,'Figyelj, azt hallottam, hogy a gazdag srác ráadásul nagyon jól főz.'::text),
(302538,33616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Arzt ... einen kleinen Hammer für das Knie.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Arzt hat einen kleinen Hammer für das Knie.'::text),
(302542,33616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікар ... маленький молоточок для коліна.'::text,'має'::text,'мати'::text,'має'::text,'Лікар має маленький молоточок для коліна.'::text),
(302541,33616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El médico ... un martillito para la rodilla.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El médico tiene un martillito para la rodilla.'::text),
(302540,33616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le médecin ... un petit marteau pour le genou.'::text,'a'::text,'ont'::text,'a'::text,'Le médecin a un petit marteau pour le genou.'::text),
(302543,33616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktorun diz için küçük bir çekici ...'::text,'var'::text,'var'::text,'var'::text,'Doktorun diz için küçük bir çekici var.'::text),
(302544,33616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvosnak ... egy kis kalapácsa a térdhez.'::text,'van'::text,'van'::text,'van'::text,'Az orvosnak van egy kis kalapácsa a térdhez.'::text),
(302556,33618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ... er sein Knie wieder beugen.'::text,'kann'::text,'kann'::text,'kann'::text,'Jetzt kann er sein Knie wieder beugen.'::text),
(302560,33618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тепер він ... знову зігнути коліно.'::text,'може'::text,'може'::text,'може'::text,'Тепер він може знову зігнути коліно.'::text),
(302559,33618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... doblar la rodilla otra vez.'::text,'puede'::text,'puede'::text,'puede'::text,'Ahora puede doblar la rodilla otra vez.'::text),
(302558,33618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant il ... plier le genou à nouveau.'::text,'peut'::text,'peut'::text,'peut'::text,'Maintenant il peut plier le genou à nouveau.'::text),
(302561,33618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Artık dizini yeniden ...'::text,'bükebilir'::text,'bükebilir'::text,'bükebilir'::text,'Artık dizini yeniden bükebilir.'::text),
(302562,33618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most már újra be ... hajlítani a térdét.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'Most már újra be tudja hajlítani a térdét.'::text),
(302565,33619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er zeigt dem Arzt seine beiden ...'::text,'Knie'::text,'Knie'::text,'Knie'::text,'Er zeigt dem Arzt seine beiden Knie.'::text),
(302569,33619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він показує лікареві обидва свої ...'::text,'коліна'::text,'коліно'::text,'коліна'::text,'Він показує лікареві обидва свої коліна.'::text),
(302568,33619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le enseña sus dos ... al médico.'::text,'rodillas'::text,'rodilla'::text,'rodillas'::text,'Le enseña sus dos rodillas al médico.'::text),
(302567,33619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il montre ses deux ... au médecin.'::text,'genoux'::text,'genou'::text,'genoux'::text,'Il montre ses deux genoux au médecin.'::text),
(302570,33619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki ... de doktora gösteriyor.'::text,'dizini'::text,'dizini'::text,'dizini'::text,'İki dizini de doktora gösteriyor.'::text),
(302571,33619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindkét ... megmutatja az orvosnak.'::text,'térdét'::text,'térdét'::text,'térdét'::text,'Mindkét térdét megmutatja az orvosnak.'::text),
(302574,33620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich bin beeindruckt, du hast den Knietest mit so viel ... und Stil gemacht.'::text,'Energie'::text,'Energie'::text,'eine Energie'::text,'Ich bin beeindruckt, du hast den Knietest mit so viel Energie und Stil gemacht.'::text),
(302578,33620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я вражена, ти пройшов тест коліна з такою ... і стилем.'::text,'енергією'::text,'енергіями'::text,'енергією'::text,'Я вражена, ти пройшов тест коліна з такою енергією і стилем.'::text),
(302577,33620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me has impresionado, hiciste la prueba de rodilla con tanta ... y estilo.'::text,'energía'::text,'energía'::text,'una energía'::text,'Me has impresionado, hiciste la prueba de rodilla con tanta energía y estilo.'::text),
(302576,33620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je suis impressionnée, tu as passé le test du genou avec tellement ... et de style.'::text,'d''énergie'::text,'d''énergie'::text,'une énergie'::text,'Je suis impressionnée, tu as passé le test du genou avec tellement d''énergie et de style.'::text),
(302579,33620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Etkilendim, diz testine o kadar çok ... ve tarzla girdin ki.'::text,'enerji'::text,'enerjiler'::text,'bir enerji'::text,'Etkilendim, diz testine o kadar çok enerji ve tarzla girdin ki.'::text),
(302580,33620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vagyok nyűgözve, akkora ... és stílussal csináltad meg a térdtesztet.'::text,'energiával'::text,'energiával'::text,'egy energiával'::text,'Le vagyok nyűgözve, akkora energiával és stílussal csináltad meg a térdtesztet.'::text),
(302583,33621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, nicht ... Leute meistern einen Knietest so wie du.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Ehrlich gesagt, nicht viele Leute meistern einen Knietest so wie du.'::text),
(302587,33621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, не ... людей так круто проходять тест коліна, як ти.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Не брехатиму, не багато людей так круто проходять тест коліна, як ти.'::text),
(302586,33621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, no ... personas bordan una prueba de rodilla como tú.'::text,'muchas'::text,'mucha'::text,'cualquier'::text,'No voy a mentir, no muchas personas bordan una prueba de rodilla como tú.'::text),
(302585,33621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, pas ... gens réussissent un test du genou comme toi.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quels'::text,'Je vais pas mentir, pas beaucoup de gens réussissent un test du genou comme toi.'::text),
(302588,33621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ... insan diz testini senin kadar iyi geçemez.'::text,'çok'::text,'çok'::text,'hiçbir'::text,'Yalan yok, çok insan diz testini senin kadar iyi geçemez.'::text),
(302589,33621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, nem ... ember teljesíti így a térdtesztet, mint te.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Nem fogok hazudni, nem sok ember teljesíti így a térdtesztet, mint te.'::text),
(302592,33622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein sehr krankes Knie, klar. Da ... null Probleme damit.'::text,'sind'::text,'ist'::text,'sein'::text,'Ein sehr krankes Knie, klar. Da sind null Probleme damit.'::text),
(302596,33622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже хворе коліно, авжеж. З ним ... нуль проблем.'::text,'є'::text,'є'::text,'бути'::text,'Дуже хворе коліно, авжеж. З ним є нуль проблем.'::text),
(302595,33622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una rodilla muy enferma, obviamente. ... ningún problema con ella.'::text,'No hay'::text,'No hay'::text,'No hay'::text,'Una rodilla muy enferma, obviamente. No hay ningún problema con ella.'::text),
(302594,33622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un genou très malade, évidemment. ... aucun problème avec lui.'::text,'Il n''y a'::text,'Il n''y a'::text,'Il n''y a'::text,'Un genou très malade, évidemment. Il n''y a aucun problème avec lui.'::text),
(302597,33622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok hasta bir diz, tabii. Onunla ilgili sıfır sorun ...'::text,'var'::text,'var'::text,'olmak'::text,'Çok hasta bir diz, tabii. Onunla ilgili sıfır sorun var.'::text),
(302598,33622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon beteg térd, persze. ... vele problémák.'::text,'Nincsenek'::text,'Nincs'::text,'Lenni'::text,'Nagyon beteg térd, persze. Nincsenek vele problémák.'::text),
(312672,34742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ... du eine Glühbirne ohne Leiter wechseln, Bro?'::text,'kannst'::text,'bist'::text,'kannst'::text,'Ey, kannst du eine Glühbirne ohne Leiter wechseln, Bro?'::text),
(312676,34742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ти ... замінити лампочку без драбини, бро?'::text,'можеш'::text,'є'::text,'можеш'::text,'Йо, ти можеш замінити лампочку без драбини, бро?'::text),
